import{m as r}from"./courses-DzPUbD19.js";function s(i){const e=`manifest-${i.number}`;return{schemaVersion:2,revision:1,id:e,courseId:"manifest",locale:"it",title:i.title,goal:i.goal,minutes:{learning:5,suggestedAction:5,review:2},direction:{hook:i.hook,reason:{id:`${e}-reason`,label:i.reason,kind:"text",maxLength:160,optional:!0,suggestions:["Il mio obiettivo; meno ripetizioni","Agire prima di preparare altro","Aiuto prima di riprovare"]},why:{id:`${e}-purpose`,label:"Perché questo passo ti serve questa settimana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:i.paragraphs,example:i.example},move:{invitation:"Mantieni l’obiettivo. Scegli un’azione utile.",instructions:i.instructions,prompts:[],suggestions:{action:i.action,minimum:i.minimum,cue:i.cue,place:i.place,fallback:i.fallback,observation:i.observation,minutes:[5,2,10],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},suggested:{action:i.action[0],minimum:i.minimum[0],minutes:5,cueHint:i.cue[0],placeHint:i.place[0],obstacleHint:i.obstacle,fallbackHint:i.fallback[0],observationHint:i.observation[0]},accessibleAlternative:"Puoi scrivere, dettare o descrivere il rituale; non servono materiali particolari né immagini mentali nitide.",stopRule:i.stopRule},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto davvero? Annota il rituale separatamente."},judgment:{primary:{id:`${e}-decision`,scenario:i.scenario,question:i.question,options:i.options.map(o=>({id:`${e}-${o.key}`,text:o.text,feedback:o.feedback})),bestOptionId:`${e}-${i.best}`}},carry:{takeaway:i.takeaway,followUp:{questionId:`${e}-return`,question:i.review,observationPrompt:"Che cosa è successo nell’occasione scelta, comprese le eventuali risposte degli altri?",adjustmentPrompt:"Quale cambiamento puoi provare alla prossima occasione?"}},goDeeper:{sections:i.deeper,sourceIds:i.sources}}}const t=[{id:"manifest-T01",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 effetti indipendenti da 21 articoli, 15.907 partecipanti: confrontare il desiderio con gli ostacoli e aggiungere un piano «se… allora…» favoriva mediamente il raggiungimento degli obiettivi, g = .336 [.229, .443]. La correzione per la distorsione da pubblicazione stimava .242 [.143, .342].",limitation:"Gli effetti variavano e c'erano indizi di distorsione da pubblicazione. Nessuna garanzia di successo, prova che il disagio sia necessario o sperimentazione di questa libreria e dei rituali adattati da ODA."},{id:"manifest-T02",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Una meta-analisi di riferimento su 94 test indipendenti, con 8.461 partecipanti, rilevava un beneficio medio nel raggiungere gli obiettivi con piani specifici «se… allora…», d = .65 [.60, .70].",limitation:"Studi meno recenti e diversi tra loro, non tutti preregistrati. Un piano non può rimuovere gli ostacoli esterni, eliminare lo sforzo o garantire la decisione di un'altra persona."},{id:"manifest-T03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 esperimenti randomizzati, 19.951 partecipanti complessivi: incoraggiare il monitoraggio dei progressi favoriva mediamente il raggiungimento degli obiettivi, d = .40 [.32, .48]. Tra gli studi, annotare i progressi era associato a effetti maggiori.",limitation:"Interventi e obiettivi diversi. I fattori associati agli effetti tra gli studi non dimostrano che ogni funzione per annotare i progressi sia efficace. Rivederli domani è un adattamento ODA, non una frequenza ottimale accertata."},{id:"manifest-T04",title:"Cole et al. · 2021 · Mental simulation and behavior change",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 studi, 123 effetti, 5.685 partecipanti: la simulazione mentale favoriva mediamente il comportamento successivo, g = .49 [.37, .62]. Il confronto complessivo non stabiliva differenze tra i tipi di simulazione.",limitation:"Campioni soprattutto di studenti, compiti e simulazioni diversi. Alcuni sottogruppi avevano pochi effetti. Non sono stati accertati una graduatoria affidabile, l'attrazione di eventi esterni o un vantaggio specifico prima di dormire."},{id:"manifest-T05",title:"Kappes & Oettingen · 2011 · Idealized positive fantasies",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Quattro esperimenti rilevavano che alcune fantasie su un futuro positivo idealizzato riducevano l'energia immediata, con alcune differenze nei risultati successivi. La fantasia piacevole va distinta dalla preparazione allo sforzo.",limitation:"Esperimenti brevi, soprattutto con studenti. Non tutto l'ottimismo o l'immaginazione è dannoso. Il presunto segnale cerebrale che farebbe considerare l'obiettivo già raggiunto non è stato misurato."},{id:"manifest-T06",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/abs/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Due esperimenti rilevavano che ripetere una frase su di sé molto positiva poteva peggiorare l'umore dei partecipanti con bassa autostima; i benefici per chi aveva alta autostima erano limitati.",limitation:"Frasi e campioni specifici, esiti a breve termine. Non dimostra che tutte le parole incoraggianti facciano male, né verifica ogni pratica di affermazione. Una frase credibile legata a un'azione è un adattamento ODA."},{id:"manifest-T07",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://pubmed.ncbi.nlm.nih.gov/25133846/",type:"research",finding:"144 test sperimentali esaminavano la riflessione su valori, qualità o relazioni importanti insieme a informazioni sulla salute. Gli effetti su accettazione e intenzioni erano piccoli; 46 test sul comportamento, con 2.715 partecipanti, davano d = .32 [.19, .44].",limitation:"Riaffermare i propri valori è diverso dal ripetere un risultato desiderato come fosse un fatto. Gli studi sui messaggi di salute non dimostrano che gli slogan ripetuti attirino lavoro, denaro o relazioni."},{id:"manifest-T08",title:"Carrillo et al. · 2019 · Best possible self meta-analysis",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 studi, 2.909 partecipanti: scrivere del miglior futuro possibile, immaginando di aver lavorato per costruirlo, migliorava mediamente benessere, ottimismo ed emozioni positive rispetto ai gruppi di controllo.",limitation:"Campioni soprattutto di giovani studenti; nessuno studio soddisfaceva tutti i criteri di qualità. Gli esiti su umore e ottimismo non provano il raggiungimento di obiettivi esterni né l'efficacia dello scripting al presente."},{id:"manifest-T09",title:"Davis et al. · 2016 · Gratitude interventions meta-analysis",url:"https://scottbarrykaufman.com/wp-content/uploads/2021/05/davis2016.pdf",type:"research",finding:"Gli studi randomizzati sulla gratitudine mostravano piccoli benefici medi sul benessere rispetto ad alcuni controlli. Per il benessere, la gratitudine non superava alternative psicologicamente attive; i risultati sull'ansia erano inconcludenti.",limitation:"Gli effetti dipendono dalle attività di confronto e dalla qualità degli studi. Non stabilisce una frequenza universale del diario, l'attrazione di eventi esterni o un effetto aggiuntivo del ringraziare per un evento futuro come se fosse già successo."},{id:"manifest-T10",title:"Cregg & Cheavens · 2021, online 2020 · Gratitude and symptom change",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 studi, 3.675 partecipanti: gli interventi di gratitudine avevano piccoli effetti medi sui sintomi di depressione e ansia analizzati insieme, maggiori rispetto alla lista d'attesa che ai controlli attivi. L'analisi separata dell'ansia comprendeva cinque studi ed era inconcludente.",limitation:"Risultati modesti sui sintomi non rendono la gratitudine un trattamento sufficiente. Per chi cerca sollievo da depressione o ansia, gli autori raccomandano interventi sostenuti da prove più solide."},{id:"manifest-T11",title:"Locke & Latham · 2002 · Goal setting and task motivation",url:"https://med.stanford.edu/content/dam/sm/s-spire/documents/PD.locke-and-latham-retrospective_Paper.pdf",type:"research",finding:"Una rassegna di decenni di ricerca sugli obiettivi descrive come obiettivi specifici e impegnativi possano favorire la prestazione. Impegno, riscontri, capacità e complessità del compito influiscono sui risultati.",limitation:"Rassegna teorica narrativa, non una verifica dei rituali di manifestazione. Servono strategie fattibili e risorse; per compiti nuovi o complessi può essere più utile puntare ad apprendere che pretendere subito una buona prestazione."},{id:"manifest-T12",title:"Frattaroli · 2006 · Expressive disclosure meta-analysis",url:"https://bpb-us-e2.wpmucdn.com/faculty.sites.uci.edu/dist/c/602/files/2019/08/Frattaroli-psych-bulletin-2006.pdf",type:"research",finding:"146 studi randomizzati sull'esprimere esperienze o emozioni rilevavano un piccolo beneficio medio nei diversi esiti, r medio = .075 [.052, .098]. Gli effetti variavano secondo l'esito e la procedura.",limitation:"Scrivere di esperienze reali è diverso dallo scrivere un desiderio come fosse un fatto. La rassegna non convalida ogni diario, non promette il recupero da un trauma e non mostra che i racconti scritti causino risultati esterni."},{id:"manifest-T13",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Manifestation beliefs",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Tre campioni di sondaggi online statunitensi, 1.023 partecipanti: credere nella manifestazione era correlato alla fiducia in sé e ad alcuni rischi finanziari e casi di fallimento finanziario dichiarati, ma non al reddito o all'istruzione dichiarati.",limitation:"Associazioni ed esiti riferiti dalle persone non stabiliscono cause, diffusione nella popolazione o efficacia di ogni tecnica. La fiducia in sé non è una prova oggettiva di successo."},{id:"manifest-T14",title:"Denrell · 2003 · Undersampling failure and success stories",url:"https://pubsonline.informs.org/doi/10.1287/orsc.14.2.227.15164",type:"research",finding:"Un'analisi dell'apprendimento dalle organizzazioni sopravvissute mostra come osservare troppo pochi insuccessi possa far sembrare associata al successo una pratica che non lo è.",limitation:"Modelli sulle organizzazioni, non uno studio del post virale fornito per il corso. Applicare questo principio di campionamento ai racconti di manifestazione è un'inferenza; non dimostra che chi racconta sia disonesto."},{id:"manifest-T15",title:"Awh, Belopolsky & Theeuwes · 2012 · Attentional control",url:"https://research.vu.nl/en/publications/top-down-versus-bottom-up-attentional-control-a-failed-theoretica/",type:"research",finding:"La rassegna sull'attenzione descrive una selezione influenzata dagli obiettivi attuali, da ciò che risalta visivamente e dalle selezioni precedenti. Un obiettivo può orientare l'attenzione, insieme ad altri fattori.",limitation:"La teoria dell'attenzione visiva non verifica vision board, affermazioni, un unico filtro dei desideri nel sistema reticolare attivante o la creazione di occasioni esterne. Notare un'occasione e farla esistere sono affermazioni diverse."},{id:"manifest-T16",title:"Dai et al. · 2023 · Behavioral priming meta-analysis",url:"https://socialactionlab.org/wp-content/uploads/2024/01/Dai_Priming-Behavior-A-Meta-Analysis-of-the-Effects-of-Behavioral-and-Nonbehavioral-Primes-on-Overt-Behavioral-Outcomes_2023.pdf",type:"research",finding:"351 studi, 862 effetti: la rassegna rilevava un effetto medio del priming sul comportamento. Il sottogruppo preregistrato, più piccolo, aveva effetti inferiori e statisticamente inconcludenti, lasciando incertezza su affidabilità e condizioni.",limitation:"Gli stimoli presentati incidentalmente negli esperimenti sono diversi dai rituali di manifestazione intenzionali. Il piccolo sottogruppo preregistrato non smentisce tutto il priming; l'insieme degli studi non convalida frasi ripetute, soglie temporali esatte o attrazione cosmica."},{id:"manifest-T17",title:"Pham & Taylor · 1999 · Process versus outcome simulation",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167299025002010",type:"research",finding:"Uno studio iniziale sugli esami favoriva l'immaginare come studiare rispetto al solo immaginare un bel voto; pianificazione e ansia contribuivano a spiegare le differenze nei voti. L'effetto principale sui voti era marginale; il confronto a posteriori tra solo processo e solo risultato era significativo.",limitation:"Nella successiva sintesi di Cole, il confronto tra simulazione del processo e controllo sui risultati d'esame non era significativo, e non emergeva un tipo sempre migliore. Uno studio iniziale circoscritto non prova aumenti affidabili dei voti rispetto al controllo o attrazione di eventi esterni."},{id:"manifest-T18",title:"Taylor et al. · 1998 · Mental simulation and self-regulation",url:"https://pubmed.ncbi.nlm.nih.gov/9572006/",type:"research",finding:"La rassegna di un programma di ricerca distingue l'immaginare il processo e come affrontare le difficoltà dal solo immaginare il risultato raggiunto, sottolineando pianificazione e soluzione dei problemi.",limitation:"Rassegna di un programma di ricerca, non una meta-analisi completa o la prova che immaginare il processo sia sempre meglio. Va letta insieme alla successiva sintesi di Cole e accompagnata da un tentativo concreto."},{id:"manifest-T19",title:"Larson-Prior, Ju & Galvin · 2014 · Sleep, wakefulness and arousal circuits",url:"https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2014.00165/full",type:"research",finding:"Una rassegna neuroscientifica descrive il sistema reticolare attivante all'interno di circuiti che interagiscono nella veglia e nell'attivazione corticale.",limitation:"Le neuroscienze della veglia non dimostrano che scrivere un desiderio programmi un filtro cerebrale capace di procurare occasioni, né che nel dormiveglia i pensieri modifichino eventi esterni. La rassegna non ha sperimentato rituali di manifestazione."},{id:"manifest-P01",title:"Taylor McGrath · 369 manifestation method",url:"https://www.theselfcollective.com.au/blogs/news/369-manifestation-method",type:"technique",finding:"Procedura descritta da una praticante: scrivi un'intenzione al presente tre volte al mattino, sei nel pomeriggio e nove la sera.",limitation:"Guida descrittiva di una praticante, non prove controllate di efficacia. Conteggi, cicli, affermazioni sull'attenzione e collegamenti a Tesla non sono risultati scientifici."},{id:"manifest-P02",title:"Victoria Jackson · Scripting an ideal day",url:"https://themanifestationcollective.co/scripting-to-manifest/",type:"technique",finding:"Procedura descritta da una praticante: racconta nel diario una giornata ideale immaginata, in prima persona e al presente. Includi sensazioni ed emozioni, poi rileggi.",limitation:"Descrive un rituale. Programmazione del subconscio, vibrazioni, sincronicità e risultati personali non sono prove da ricerche controllate."},{id:"manifest-P03",title:"Jack Canfield · Creating a vision board",url:"https://jackcanfield.com/blog/vision-board/",type:"technique",finding:"Procedura descritta da un praticante: scegli obiettivi e immagini o parole che li rappresentano, crea un collage fisico o digitale, esponilo e riguardalo regolarmente.",limitation:"Guida descrittiva, non prove di efficacia delle vision board. Questa pagina non dimostra la legge dell'attrazione, i racconti di successo o le spiegazioni basate sul sistema reticolare attivante."},{id:"manifest-P04",title:"Jack Canfield · Daily affirmations",url:"https://jackcanfield.com/blog/daily-affirmations/",type:"technique",finding:"Procedura descritta da un praticante: crea frasi brevi e specifiche, in prima persona e al presente. Leggile o ripetile, spesso al mattino e alla sera.",limitation:"Le frasi positive sono diverse dalla ricerca sulla riaffermazione dei propri valori. La guida non stabilisce benefici universali o effetti sui risultati esterni."},{id:"manifest-P05",title:"Jack Canfield · Visualization techniques",url:"https://jackcanfield.com/blog/visualization-techniques-manifest-your-dreams/",type:"technique",finding:"La guida di un praticante descrive l'immaginare il risultato desiderato con dettagli sensoriali, il provare mentalmente in prima persona e l'immaginare il processo per raggiungere un obiettivo.",limitation:"Indicazioni descrittive, non prove a sostegno di garanzie o dell'attrazione. I risultati empirici sulla simulazione vanno verificati nelle fonti di ricerca."},{id:"manifest-P06",title:"Zanna Keithley · 55x5 method description",url:"https://zannakeithley.com/55x5-manifestation-method-worksheet/",type:"technique",finding:"Procedura descritta da una praticante: scrivi un'affermazione 55 volte di seguito per cinque giorni consecutivi, immaginando che sia già vera.",limitation:"Basta la descrizione pubblica; non serve acquistare la scheda. Conteggi e spiegazioni sulle vibrazioni elevate non sono prove accertate di efficacia."},{id:"manifest-P07",title:"Practitioner account · Two-cup method",url:"https://www.reddit.com/r/Manifestation/comments/1poqa0q/insanely_powerful_technique/",type:"technique",finding:"Procedura raccontata in prima persona: etichetta due bicchieri con la situazione attuale e quella desiderata, immagina il cambiamento, versa l'acqua dal primo nel secondo, poi bevila.",limitation:"Racconto anonimo di chi pratica il metodo, non prove verificate di un nesso causale. Cambiare realtà e forzare risultati sono affermazioni prive di sostegno. Usa acqua potabile senza aggiunte e bicchieri puliti."},{id:"manifest-P08",title:"Sandy · Pillow method guide",url:"https://theprettythoughts.com/the-pillow-method-an-easy-way-to-manifest/",type:"technique",finding:"Procedura descritta da una praticante: scrivi un desiderio al presente, piega il foglio e mettilo sotto il cuscino, poi ripetilo o immaginalo mentre ti prepari a dormire.",limitation:"Conteggi e pieghe variano. Le affermazioni su foglio, subconscio, cristalli, oli e attrazione non sono prove controllate di efficacia."},{id:"manifest-P09",title:"Sandy · Whisper method guide",url:"https://theprettythoughts.com/the-viral-whisper-method-manifestation-technique/",type:"technique",finding:"Procedura descritta da una praticante: rilassati, immagina di avvicinarti a un'altra persona, sussurrale all'orecchio tre volte la richiesta desiderata, poi esci dalla scena immaginata.",limitation:"Testimonianza personale, non prove di telepatia. Una richiesta immaginata non dimostra il controllo su un'altra persona e non può sostituirne il consenso né scavalcarne i limiti."},{id:"manifest-P10",title:"Simi · The Gratitude Game",url:"https://www.thesecret.tv/stories/the-gratitude-game/",type:"technique",finding:"Il racconto in prima persona descrive un diario della gratitudine: scrivi ciò che apprezzi insieme ai motivi, poi rileggi.",limitation:"Racconto personale, non ricerca su un intervento. La storia non dimostra che la gratitudine attiri eventi o elimini problemi."},{id:"manifest-P11",title:"Alexandra · Act as if it is already done",url:"https://www.thesecret.tv/stories/act-as-if-its-already-done/",type:"technique",finding:"Il racconto in prima persona descrive il preparare vestiti e bagagli come se il lavoro desiderato fosse confermato, immaginando il risultato voluto.",limitation:"L'autrice riferisce un'offerta da una persona che già conosceva. Un aneddoto non può isolare le cause o confermare una legge generale dell'attrazione."},{id:"manifest-P12",title:"Victoria Jackson · Letter from your future self",url:"https://themanifestationcollective.co/wp-content/uploads/2021/04/Scripting-To-Success-Masterclass.pdf",type:"technique",finding:"La risorsa di una praticante descrive una versione futura immaginata di te che scrive al tuo io presente, racconta i cambiamenti di vita e offre comprensione.",limitation:"Le pagine 6-7 documentano la pratica, non comunicazioni dal futuro o efficacia sui risultati esterni. Data e saluto sono scelte facoltative del formato della lettera."},{id:"manifest-P13",title:"Abraham / Esther and Jerry Hicks · 17-second focus",url:"https://spiritlibrary.com/abraham-hicks/only-17-seconds-away-from-your-true-desires",type:"technique",finding:"La trascrizione dell'insegnamento invita a mantenere un pensiero desiderato per 17 secondi senza contraddirlo; la variante con quattro intervalli arriva a 68 secondi.",limitation:"Insegnamento spirituale, non prove controllate. Soglie esatte, combustione dei pensieri, manifestazione fisica ed equivalenza dichiarata con ore di lavoro sono prive di sostegno."},{id:"manifest-P14",title:"Amy Parker · Creating a manifestation box",url:"https://envibelife.com/creating-a-manifestation-box/",type:"technique",finding:"Procedura raccontata in prima persona: metti in una scatola cartoncini con intenzioni o immagini, includi le emozioni desiderate e torna a rivedere il contenuto.",limitation:"Documenta una pratica simbolica. Le spiegazioni sul campo energetico e sulla manifestazione sono credenze, non risultati scientifici. Basta un contenitore che hai già."},{id:"manifest-P15",title:"Neville Goddard · Five Lessons, 1948",url:"https://readnevillegoddard.com/five-lessons/",type:"technique",finding:"Il testo originale dell'insegnante descrive rilassamento nel dormiveglia, una breve scena di desiderio realizzato, partecipazione in prima persona e ripetizione finché l'azione immaginata sembra reale.",limitation:"La trascrizione gratuita documenta l'insegnamento SATS, non l'efficacia. Le affermazioni metafisiche sui risultati esterni e sull'assenza di azioni necessarie non sono prove scientifiche; proteggi il sonno."}],l=[{number:6,technique:"Metodo 3-6-9",title:"3-6-9: dal quaderno alla candidatura",goal:"Tieni il quaderno e fai un passo verso un obiettivo preciso.",hook:"Scrivi ancora «Ho ottenuto il lavoro»? Manda una candidatura all’azienda sull’altra pagina.",reason:"Questo quaderno ti avvicina al lavoro che vuoi o sottrae tempo alle candidature?",paragraphs:["Il metodo 3-6-9 ripete un’affermazione al presente tre volte al mattino, sei a mezzogiorno, nove la sera. Nella variante a due pagine: aziende desiderate a sinistra, «Ho ottenuto il lavoro» a destra. Non supportato: che quei numeri attirino un’offerta. Una storia di successo non distingue ripetizioni e candidature, né mostra i tentativi senza esito.","Versione ODA: tieni le pagine; il ritmo è facoltativo. A sinistra: obiettivi precisi e un passo di oggi per candidarti, chiedere aggiornamenti o prepararti. A destra: una frase credibile su di te e «se… allora…» per un ostacolo. La ricerca sostiene piani con situazioni e risposte precise. Agisci oggi; domani valuta tentativo e risposte separatamente."],example:{title:"Giulia usa entrambe le pagine",text:"Giulia scrive due aziende di logistica a sinistra e «Preparo candidature utili» a destra. Dopo pranzo controlla un annuncio e invia un curriculum mirato. Il piano dice: «Se il portale non funziona, salvo la bozza e contatto chi seleziona». Un portale non funziona. Annota la richiesta inviata; nessuna delle aziende ha fatto un’offerta."},instructions:["Pagina sinistra: indica l’obiettivo e il passo per candidarti, chiedere aggiornamenti o prepararti oggi.","Pagina destra: aggiungi una frase credibile su di te e un piano per un ostacolo.","Fai quel passo; domani valuta il tuo tentativo e le eventuali risposte."],action:["Invia una candidatura mirata","Chiedi aggiornamenti a un’azienda"],minimum:["Invia una candidatura adatta","Invia una domanda di aggiornamento"],cue:["Dopo pranzo","Quando finisco di scrivere al mattino"],place:["Alla scrivania per le candidature","Sul portale candidature dell’azienda"],obstacle:"Il portale candidature non si carica",fallback:["Salva la bozza e contatta chi seleziona","Scegli un’altra opportunità disponibile per candidarti"],observation:["Invio o richiesta, ed eventuale risposta","Il passo che ho completato davvero"],stopRule:"Salta le ripetizioni che tolgono spazio all’azione; sospendi le candidature inadatte o troppo costose.",scenario:"Giulia ha scritto tutte le 18 ripetizioni ed elencato tre aziende. Un annuncio adatto scade stasera. La candidatura richiede un breve paragrafo sulla sua esperienza.",question:"Cosa dovrebbe produrre la prossima volta che apre il quaderno?",options:[{key:"repeat",text:"Seguire il programma di ripetizioni e scrivere una frase più lunga su di sé prima di tornare alla candidatura.",feedback:"La frase può restare nel rituale, ma allungarla non completa la candidatura. La scadenza è vicina: usa il quaderno per ricordarti di scrivere il paragrafo richiesto."},{key:"submit",text:"Scrivere il paragrafo richiesto, inviare la candidatura e annotare l’invio separatamente dalle eventuali risposte dell’azienda.",feedback:"Questo rispetta l’obiettivo preciso e la scadenza. L’invio dipende da lei; la risposta no. Se le piace, può tenere il rituale e poi valutare quello che è successo davvero."},{key:"expand",text:"Ampliare prima l’elenco delle aziende, così domani potrà cercare lavoro tra più possibilità.",feedback:"Una ricerca più ampia potrà servire dopo. Stasera c’è già un annuncio adatto con una scadenza precisa. Aggiungere aziende rimanderebbe la candidatura disponibile. Prima completa il paragrafo mancante."}],best:"submit",takeaway:"Usa il quaderno per avviare una candidatura. Conta separatamente azioni e risposte.",review:"Quale passo verso l’obiettivo hai tentato? Qualche azienda ha risposto?",deeper:[{heading:"Il metodo conosciuto, con le due pagine",paragraphs:["1. Scegli un risultato desiderato e descrivilo come già raggiunto. 2. Scrivi l’affermazione tre volte al mattino. 3. Ripetila sei volte verso mezzogiorno. 4. Scrivila nove volte la sera. Questi numeri descrivono la ricetta diffusa, non una dose sostenuta dalla ricerca. I racconti di chi la pratica indicano durate diverse per questo programma. [manifest-P01]","5. Nell’esempio a due pagine fornito per questo corso, a destra c’è «Ho ottenuto il lavoro»; a sinistra le aziende a cui si è candidata e quelle desiderate. Racconta di aver ricevuto un’offerta da un’azienda elencata. È un racconto fornito per il corso, non dati sperimentali verificati indipendentemente. Parlare qui di distorsione da sopravvivenza è un’inferenza: il successo visibile esclude chi ha provato il rituale senza ricevere offerte. Il racconto può essere sincero senza chiarirne la causa. [manifest-T14]"]},{heading:"Tieni il ritmo, cambia ciò che ti ricorda",paragraphs:["Le prove sulla pianificazione riguardano una situazione riconoscibile collegata a una risposta fattibile. Non dimostrano che tre, sei o nove ripetizioni influenzino un datore di lavoro. Se ti piace, tieni il conteggio e affiancagli il compito: un’azienda, un annuncio adatto e l’azione di oggi. L’elenco a sinistra e le candidature reali offrono un percorso pratico verso un’offerta; questo aneddoto non dimostra cosa abbia causato quella ricevuta. [manifest-T02, manifest-T14]","A destra prova «Preparo candidature utili». Aggiungi «Se il portale non funziona, salvo la bozza e contatto chi seleziona». Controlla scadenza, accesso e tempo disponibile. Invia o chiedi oggi, poi annota l’azione precisa. Domani verifica le risposte dell’azienda senza leggere il silenzio come una mancanza di fiducia. Ripetizioni, preparazione, candidature e offerte restano voci separate. Questo uso delle due pagine è un adattamento ODA, non un intervento sperimentato. [manifest-T02]"]}],sources:["manifest-P01","manifest-T02","manifest-T14"]},{number:7,technique:"Scripting",title:"Scripting: nel futuro scrivi anche il lavoro",goal:"Usa una scena futura per scegliere e tentare un’azione verso il tuo obiettivo.",hook:"La giornata immaginata finisce benissimo. Cosa hai fatto prima di colazione per arrivarci?",reason:"Cosa ti aiuterà a fare questa pagina prima di scriverne un’altra?",paragraphs:["Lo scripting descrive nel diario il futuro desiderato come se accadesse adesso. Scegli una scena, descrivi dettagli ed emozioni, poi rileggi. Prove miste: scrivere del proprio miglior futuro possibile ha migliorato in media benessere e ottimismo; non dimostra che scrivere al presente produca gli eventi. Gli studi sulla scrittura espressiva riguardano esperienze reali, non desideri che diventano fatti.","Versione ODA: tieni la scena, includendo il lavoro necessario per arrivarci. Indica un obiettivo preciso, un ostacolo attuale e una risposta «se… allora…». Sottolinea un’azione da tentare oggi. Domani confronta tentativo e piano, invece di chiederti se l’intera scena si è avverata. L’esercizio combinato è un adattamento."],example:{title:"Elena aggiunge il lavoro mancante",text:"Elena descrive una mattina serena in un nuovo ruolo. Aggiunge la preparazione al colloquio che dovrebbe precederla. Dopo cena registra una risposta su come ha gestito un cliente difficile. Si sente parlare troppo in fretta e segna una frase da accorciare. Il lavoro è ancora ipotetico, ma c’è una registrazione vera da migliorare domani."},instructions:["Scrivi la scena futura, includendo il lavoro e le risorse necessari.","Sottolinea l’azione di oggi; aggiungi «Se incontro questo ostacolo, allora…».","Prova a fare il minimo scelto e domani valuta cosa è successo."],action:["Registra una risposta da colloquio","Scrivi una didascalia per il portfolio"],minimum:["Salva la registrazione di una risposta","Salva una didascalia utilizzabile"],cue:["Dopo aver sparecchiato la cena","Quando chiudo il diario"],place:["Al tavolo della cucina","Nel documento del portfolio"],obstacle:"Non trovo la frase iniziale perfetta",fallback:["Usa una prima frase provvisoria","Chiedi un esempio preciso"],observation:["La registrazione che ho salvato","La bozza e ciò che manca ancora"],stopRule:"Salta le scene che ti causano disagio; scegli normali appunti sul compito se scrivere del futuro non ti aiuta.",scenario:"Il diario di Elena descrive un colloquio sicuro. Il colloquio è domani e non ha pronto un esempio per una domanda frequente sul servizio clienti.",question:"Quale modifica rende utile la pagina stasera?",options:[{key:"draft",text:"Aggiungere un episodio vero con un cliente, provare una risposta e salvarne una registrazione provvisoria da controllare domani.",feedback:"Questo collega la scena al compito di domani. Una risposta provvisoria può mostrare cosa migliorare. Non garantisce il lavoro, ma produce una preparazione che Elena può ascoltare e correggere."},{key:"feelings",text:"Descrivere meglio la sensazione di sicurezza prima di decidere quale episodio con un cliente usare.",feedback:"Esplorare le emozioni può dare senso alla scena. Qui manca una risposta basata su un’esperienza vera. Aggiungere dettagli emotivi lascia il problema irrisolto: scegli un episodio e prova a raccontarlo."},{key:"edit",text:"Rifinire tutta la pagina di diario per dare al colloquio immaginato un racconto chiaro e coerente.",feedback:"Scrivere una storia coerente è un obiettivo di scrittura. Ora Elena deve preparare una risposta. Rifinire il racconto occupa il poco tempo della serata senza produrre l’esempio che serve al colloquio."}],best:"draft",takeaway:"Scrivi un futuro che vuoi costruire, poi fai oggi una parte del lavoro necessario.",review:"Quale passo scritto hai tentato davvero? Cosa resta da finire?",deeper:[{heading:"Come si pratica lo scripting",paragraphs:["1. Scegli una situazione desiderata, come una giornata nel ruolo che vorresti. 2. Scrivi una pagina di diario come se stesse accadendo ora. 3. Descrivi dettagli quotidiani: dove sei, cosa fai e quali emozioni provi. 4. Rileggi e torna alla pagina se vuoi. Alcune versioni aggiungono gratitudine o una sensazione di certezza. Sono istruzioni di chi pratica il metodo, non un percorso verificato per ricevere un’offerta. [manifest-P02]","Indica chiaramente che gli eventi immaginati sono immaginati. Puoi descrivere una scena quotidiana senza inventare promesse di altre persone. Nell’esercizio ODA aggiungi il lavoro necessario, le risorse disponibili e un ostacolo attuale. Scegli un solo compito dalla pagina. Scrivere al computer o registrare a voce sono alternative accessibili; non sosteniamo che ogni formato abbia effetti identici nella ricerca. Il rituale resta facoltativo. [manifest-P02]"]},{heading:"Scrivere del futuro e delle esperienze reali è diverso",paragraphs:["La ricerca sul miglior futuro possibile chiede di immaginare un buon futuro e il lavoro svolto per raggiungerlo. Carrillo e colleghi hanno trovato benefici medi per benessere, ottimismo ed emozioni positive, con limiti nella qualità degli studi. Questo permette aspettative circoscritte sulla scrittura riflessiva. Non dimostra che lo scripting al presente faccia accadere gli eventi descritti. La scrittura espressiva ha un altro oggetto: esperienze o emozioni reali. Neppure il suo piccolo beneficio medio convalida l’attrazione di eventi futuri. [manifest-T08, manifest-T12]","ODA tiene il racconto e aggiunge un modo pratico per uscirne. Scegli un obiettivo preciso già presente nella prova che stai facendo nel corso. Indica cosa potrebbe bloccare il passo di oggi, poi scrivi una risposta che puoi permetterti e mettere in pratica. Salva quando agire e il minimo scelto, prova e valuta domani. Annota la prova del colloquio come preparazione, la candidatura come invio e una risposta solo quando arriva. Questo percorso è un adattamento progettuale, non uno dei due interventi di scrittura nella forma studiata."]}],sources:["manifest-P02","manifest-T08","manifest-T12"]},{number:8,technique:"Vision board",title:"Vision board: dai un compito a un’immagine",goal:"Trasforma un’immagine della bacheca in un promemoria per un’azione fattibile.",hook:"Bella, quella scrivania sulla vision board. Cosa farai oggi alla tua?",reason:"Quale immagine rappresenta una tua priorità, anziché l’idea di successo di qualcun altro?",paragraphs:["Una vision board raccoglie immagini e parole della vita desiderata. Scegli e disponi le immagini, esponi la bacheca e riguardala. Prove miste: gli obiettivi attuali possono orientare l’attenzione, insieme a ciò che risalta e alle esperienze passate. Questo non dimostra l’efficacia della bacheca né che le immagini attirino opportunità. Il sistema reticolare attivatore riguarda l’attivazione; definirlo un filtro programmabile dei desideri supera le prove.","Versione ODA: tieni un’immagine significativa. Scrivi accanto l’obiettivo preciso e un’azione di oggi. Indica un ostacolo e una risposta «se… allora…»; usa l’immagine per ricordarti di iniziare. Domani controlla se ti ha portato al minimo scelto. Notare un’opportunità è diverso dal crearla."],example:{title:"Nora annota il compito",text:"La bacheca di Nora mostra una scrivania in uno studio di design. Accanto scrive «Prepara un lavoro per il portfolio». Quando vede la foto dopo colazione, apre il progetto incompleto e scrive una didascalia. La didascalia le sembra meno emozionante del sogno dello studio. La salva comunque e annota che il progetto ha ancora bisogno di un parere."},instructions:["Scegli un’immagine; aggiungi l’obiettivo preciso e l’azione utile di oggi.","Usala per ricordarti di iniziare; decidi cosa fare se incontri un ostacolo probabile.","Prova l’azione e domani controlla se hai notato il promemoria."],action:["Scrivi una didascalia per il portfolio","Chiedi un parere su un progetto"],minimum:["Salva una didascalia utilizzabile","Invia una domanda mirata per un parere"],cue:["Quando vedo la bacheca dopo colazione","Quando apro la cartella del progetto"],place:["Alla mia scrivania","Nel documento del portfolio"],obstacle:"L’immagine mi porta a curiosare invece di lavorare",fallback:["Apri il progetto prima di curiosare","Metti un promemoria scritto accanto al file"],observation:["Se l’immagine mi ha fatto iniziare davvero","La didascalia o la richiesta completata"],stopRule:"Usa immagini o parole che hai già; evita immagini che ti spingono a spendere.",scenario:"Nora vede la bacheca ogni mattina, poi guarda foto di studi di design. Nel portfolio manca la didascalia che spiega un progetto completato.",question:"Quale cambiamento è più utile?",options:[{key:"fresh",text:"Sostituire la foto dello studio con una più stimolante, così la bacheca tornerà a sembrarle significativa.",feedback:"Una foto nuova può piacerle, ma le note mostrano che dopo il promemoria si mette a curiosare. Non manca un’aspirazione. Cambia quello che l’immagine le chiede di fare."},{key:"study",text:"Passare la prossima mattina a confrontare portfolio di studi per capire il livello che vorrebbe raggiungere.",feedback:"Il confronto potrà orientare il lavoro futuro. Nora ha già un progetto completato a cui manca la didascalia. Continuare a curiosare ripeterebbe lo stesso schema, salvo rispondere a una domanda precisa necessaria per scriverla."},{key:"label",text:"Scrivere accanto alla foto «Apri il progetto, scrivi la didascalia» e salvarne una prima di guardare altre foto di studi.",feedback:"Questo collega il promemoria esistente all’azione mancante. Domani Nora potrà verificare se ha notato la scritta e salvato la didascalia. La bacheca da sola non garantisce un posto in uno studio."}],best:"label",takeaway:"Dai all’immagine un compito da ricordarti. Valuta il compito, non il potere della foto.",review:"Vedere l’immagine ti ha portato all’azione salvata o a fare altro?",deeper:[{heading:"Crea la bacheca senza comprare nulla",paragraphs:["1. Scegli una direzione o una situazione desiderata. 2. Raccogli qualche immagine e parola che la rappresenti. 3. Disponile su carta, su una bacheca che hai già o su una pagina digitale. 4. Metti la raccolta dove vuoi riguardarla. 5. Osservala e immagina la situazione desiderata. Questi passi descrivono l’esercizio praticato, non provano che una bacheca faccia esistere quella situazione. [manifest-P03]","Per questo corso, tieni una direzione senza aggiungere ogni possibile miglioramento della vita. Bastano una foto che hai già, uno schizzo o una parola scritta. Sotto un’immagine indica il compito vero: chiedere un dettaglio su un corso, finire un lavoro o inviare una candidatura adatta. Scegli un luogo dove puoi agire quando compare l’immagine. Materiali e disposizione dipendono da te; non esiste un requisito scientifico che imponga acquisti speciali. Disponi le immagini e completa il compito come due attività distinte."]},{heading:"Cosa può spiegare accorgersi di un’opportunità",paragraphs:["La ricerca sull’attenzione descrive una selezione influenzata dagli obiettivi attuali, da ciò che risalta fisicamente e da ciò a cui hai prestato attenzione in passato. Questo rende plausibile cercare intenzionalmente opportunità pertinenti; non convalida ogni metodo proposto per notarle meglio. Il sistema reticolare attivatore partecipa ai circuiti di veglia e attivazione. Questi risultati non dimostrano un filtro controllato dalla bacheca capace di procurare lavoro, partner o casa. Un’opportunità appena notata poteva esistere già prima che le prestassi attenzione. [manifest-T15, manifest-T19]","ODA usa l’immagine come promemoria esplicito, senza attribuirle un meccanismo nascosto. Scrivi l’obiettivo, l’azione di oggi e cosa farai davanti all’ostacolo che più probabilmente la interromperà. Se vedere la bacheca ti fa ricominciare a curiosare, pianifica di aprire prima il file di lavoro. Domani verifica se il promemoria si è presentato, se l’hai notato e cosa hai fatto davvero. Tieni separate le risposte esterne. Questo insieme di immagine e piano non è stato sperimentato come intervento con vision board."]}],sources:["manifest-P03","manifest-T15","manifest-T19"]},{number:9,technique:"Affermazioni",title:"Affermazioni: scegli una frase utile",goal:"Collega una frase incoraggiante a un’azione osservabile verso l’obiettivo.",hook:"«Sono una persona di enorme successo» ti suona falso? Scegli una frase che ti faccia agire.",reason:"La frase ti aiuta a provare o ti impone certezza?",paragraphs:["Le affermazioni ripetono incoraggiamenti a voce o per iscritto, spesso presentando il risultato come già raggiunto. Scegli una frase, ripetila e immagina di crederci. Prove miste: Wood e colleghi osservavano che una frase molto positiva peggiorava l’umore di alcuni partecipanti con bassa autostima. Nella ricerca l’autoaffermazione spesso implica riflettere su valori importanti, non slogan di successo; i risultati sui comportamenti di salute non dimostrano l’attrazione di un lavoro.","Versione ODA: tieni una frase incoraggiante utilizzabile. Collega un valore all’azione che lo esprime: «Preparo un esempio sincero». Scegli l’obiettivo preciso, un ostacolo e una risposta «se… allora…». Prova oggi; domani valuta cosa hai fatto. Cambia o salta frasi che ti fanno stare peggio."],example:{title:"Laura cambia la frase",text:"Prima della riunione Laura ripete «Sono bravissima a parlare in pubblico» e si sente più in imbarazzo. Passa a «Preparo un punto chiaro». Alla scrivania scrive una proposta e prova a dirla. In riunione pronuncia la prima frase, poi perde il filo. Annota il contributo dato e la spiegazione lasciata a metà."},instructions:["Scegli una frase incoraggiante collegata a un valore e a un’azione precisa.","Indica un ostacolo; aggiungi una risposta fattibile «se… allora…», senza obbligarti a crederci.","Prova l’azione oggi; domani valuta cosa hai fatto e come ti sentivi con la frase."],action:["Usa una frase preparata in riunione","Fai una domanda chiara sul progetto"],minimum:["Di’ la prima frase della proposta","Invia una domanda precisa sul progetto"],cue:["Quando in riunione si chiedono proposte","Quando apro la conversazione sul progetto"],place:["Nella sala riunioni","Nella conversazione sul progetto"],obstacle:"La frase incoraggiante mi sembra falsa",fallback:["Usa la frase preparata senza affermazioni","Passa a un semplice promemoria dell’azione"],observation:["Cosa ho detto e la risposta","Se la frase ha aiutato o peggiorato l’umore"],stopRule:"Cambia o salta le frasi che ti causano disagio; non devi costringerti a provare certezza.",scenario:"La frase di successo che Laura ripete la fa stare peggio. Vuole comunque fare una proposta utile in riunione e ha già pronta una frase provvisoria.",question:"Quale cambiamento tiene conto di entrambi i fatti?",options:[{key:"persist",text:"Continuare ancora per qualche sessione con la frase di successo prima di cambiarla, continuando a provare la proposta.",feedback:"La prova può aiutare a prepararsi, ma non è obbligatorio insistere con una frase che peggiora l’umore. La proposta pronta offre a Laura un altro modo di iniziare senza costringersi a crederci."},{key:"action",text:"Usare un semplice promemoria dell’azione o saltare l’affermazione, poi dire la frase preparata quando si chiedono proposte.",feedback:"Questo mantiene un contributo fattibile e tiene conto del disagio riferito. Laura potrà valutare cosa ha detto e come l’ha fatta sentire il promemoria. Non serve la certezza di essere bravissima a parlare."},{key:"wait",text:"Preparare una frase più forte sulle proprie qualità e rimandare la proposta finché non si sentirà più convinta.",feedback:"Riflettere sui valori è diverso dal convincersi di una frase grandiosa. Aspettare di crederci rende la sicurezza una condizione per un’azione già pronta. Tieni piccolo il contributo e facoltativa la frase."}],best:"action",takeaway:"La frase è un promemoria facoltativo. Lascia che l’azione fornisca prove.",review:"Cosa hai tentato? La frase ti ha aiutato, ostacolato o non ha cambiato nulla?",deeper:[{heading:"La pratica diffusa delle affermazioni",paragraphs:["1. Scegli un risultato o una qualità personale. 2. Esprimilo in positivo, spesso al presente. 3. Ripetilo a voce o per iscritto. 4. Immagina la situazione desiderata mentre usi la frase. 5. Torna alla frase in un momento scelto. Frequenza e parole variano tra le versioni praticate; la ricetta conosciuta non stabilisce un conteggio o un’emozione richiesti dalla scienza. [manifest-P04]","Puoi apprezzare la pratica senza accettarne la promessa più forte. Per ODA usa una frase che indichi un lavoro che puoi tentare davvero. «Preparo un punto chiaro» può stare accanto agli appunti della riunione. Puoi anche non usare nessuna frase. Un’affermazione scomoda o poco credibile non è una prova da superare. Wood e colleghi hanno studiato una particolare frase positiva e gli effetti a breve termine sull’umore; il risultato non dimostra che ogni parola gentile faccia male. [manifest-T06]"]},{heading:"Un valore è diverso da uno slogan di successo",paragraphs:["Nella ricerca sull’autoaffermazione le persone spesso riflettono su valori, qualità o relazioni importanti prima di incontrare informazioni potenzialmente minacciose. Epton e colleghi hanno riunito esperimenti con messaggi sulla salute e trovato piccoli effetti medi sull’accettazione e sulle intenzioni, con un beneficio comportamentale in quel contesto. Queste procedure sono diverse dal ripetere un risultato desiderato come già vero. Non dimostrano che dire «Ho ottenuto il lavoro» faccia arrivare un’offerta. [manifest-T07]","ODA riprende questa distinzione senza dichiarare sperimentato tutto il rituale. Scegli un valore, come l’onestà, e un modo di esprimerlo nel tuo obiettivo attuale: prepara un esempio accurato del tuo lavoro. Salva quando agire e il minimo scelto. Scrivi cosa farai davanti a un ostacolo probabile, come perdere il filo, e prova a dire la frase oggi. Domani annota il contributo reale e se la frase ti è servita. Salta l’affermazione se aggiunge pressione; tieni l’azione fattibile. [manifest-T06, manifest-T07]"]}],sources:["manifest-P04","manifest-T06","manifest-T07"]},{number:10,technique:"Visualizzazione",title:"Visualizzazione: nella scena prova cosa fare",goal:"Scegli un compito, affronta mentalmente una difficoltà e fai un tentativo reale.",hook:"Immagini l’offerta di lavoro? Prova a rispondere alla domanda che viene prima.",reason:"Un’altra scena mostrerà una lacuna utile o rimanderà un’azione già pronta?",paragraphs:["Visualizzare significa immaginare un evento desiderato, spesso con dettagli sensoriali e sensazioni di successo. Mettiti comodo, immagina la scena, partecipa mentalmente e ripeti se vuoi. Prove miste per la manifestazione: la simulazione mentale favoriva in media comportamenti successivi, senza dimostrare l’attrazione di eventi. Un primo studio sugli esami favoriva l’immaginazione del processo in alcuni confronti; la successiva meta-analisi non stabiliva un tipo affidabilmente migliore.","Versione ODA: tieni una breve scena del risultato, poi prova mentalmente il compito reale e un ostacolo. Scegli un obiettivo preciso e una risposta «se… allora…», tenta un’azione oggi e valuta domani. La prova mentale resta preparazione. Se non crei immagini, scrivi i passi: non servono immagini vivide o emozioni speciali."],example:{title:"Matteo prova la domanda difficile",text:"Matteo immagina il colloquio concluso, poi prova a spiegare un periodo senza lavoro. Se si blocca, inizierà dalle date. Dopo pranzo registra una risposta e nota di aver omesso cosa ha imparato. Aggiunge una frase. La risposta richiede ancora esercizio; non c’è un esito del colloquio."},instructions:["Tieni breve la scena del risultato; prova il prossimo compito e una difficoltà probabile.","Scrivi un obiettivo preciso e una risposta «se… allora…» per quella difficoltà.","Fai il tentativo reale oggi e domani valutalo separatamente dalla prova mentale."],action:["Registra una risposta di prova al colloquio","Invia una proposta preparata per la riunione"],minimum:["Salva una registrazione provvisoria della risposta","Invia una frase con una proposta"],cue:["Dopo pranzo","Quando in riunione si chiedono contributi"],place:["Alla scrivania per preparare il colloquio","Nella conversazione del gruppo"],obstacle:"Mi blocco alla prima frase",fallback:["Inizia dalle date negli appunti","Leggi il breve inizio preparato"],observation:["La risposta che ho registrato davvero","Preparazione e contributo reale annotati separatamente"],stopRule:"Interrompi le immagini se aumentano il disagio; usa normali appunti sul compito e un momento di giorno.",scenario:"Matteo ha immaginato due volte un colloquio riuscito. La risposta di prova salvata evita ancora di spiegare il periodo senza lavoro. Ha cinque minuti prima di uscire.",question:"Come può usare l’immaginazione per questa lacuna?",options:[{key:"rehearse",text:"Provare la prima frase che spiega il periodo senza lavoro, registrare una risposta provvisoria e controllare che includa le date necessarie.",feedback:"Così la preparazione affronta la lacuna osservata e produce una registrazione da controllare. L’immaginazione non garantisce l’esito del colloquio. Qui può aiutare Matteo a provare a dare quella risposta."},{key:"outcome",text:"Ripetere la scena del colloquio riuscito con più dettagli, poi annotare quanto lo fa sentire sicuro.",feedback:"La sicurezza è un’osservazione possibile, ma non risponde alla domanda mancante. Le note di Matteo indicano una spiegazione precisa da provare. Usa il tempo rimasto per provarla e registrarla."},{key:"research",text:"Usare il tempo per confrontare vari metodi di visualizzazione prima di decidere quale praticare stasera.",feedback:"Confrontare metodi può essere interessante, ma qui nessuna prova richiede di sceglierne un tipo prima di iniziare. Matteo conosce già il compito mancante. Un tentativo breve dà informazioni più pertinenti di un’altra ricerca sui metodi."}],best:"rehearse",takeaway:"La scena può mostrare un compito. La prova prepara; il tentativo verifica.",review:"Cosa hai tentato davvero dopo la prova mentale? Quale lacuna è emersa?",deeper:[{heading:"La scena conosciuta del risultato desiderato",paragraphs:["1. Scegli un evento che vorresti accadesse. 2. Mettiti comodo. 3. Immagina una breve scena che mostri il risultato desiderato. 4. Immagina di partecipare, con dettagli significativi per te. 5. Torna alla scena se vuoi. Alcune versioni richiedono emozioni forti o la sensazione di avere già il risultato. Queste istruzioni documentano un rituale; non dimostrano che la scena attiri un evento esterno. [manifest-P05]","Per ODA tieni la scena abbastanza breve da lasciare tempo al lavoro. Individua il prossimo compito tra il presente e quella scena. Prova mentalmente una difficoltà del compito, poi scrivi la risposta che tenterai. Chi non forma immagini vivide può descrivere i passi. È un’alternativa accessibile, non la prova che tutti i formati di preparazione abbiano lo stesso effetto. Non annotare mai una risposta immaginata dell’azienda come se fosse vera."]},{heading:"Nessun tipo di immaginazione vince sempre",paragraphs:["Il primo studio sugli esami di Pham e Taylor confrontava immagini del processo di studio, del voto desiderato, combinazioni e un gruppo di controllo. Alcuni confronti favorivano il processo; il risultato sui voti non giustifica un beneficio affidabile rispetto al controllo. Cole e colleghi hanno poi riunito simulazioni mentali diverse, trovando un beneficio comportamentale medio senza stabilire differenze tra tipi. Vari sottogruppi erano piccoli. Promettere che una scena funzioni sempre meglio andrebbe oltre queste prove. [manifest-T17, manifest-T04]","ODA chiede quale preparazione serva al tuo compito. Se conosci l’obiettivo ma eviti la prima frase, prova a iniziare e ad affrontare quell’ostacolo. Salva un minimo fattibile, quando iniziare, il luogo e la risposta prevista. Prova l’azione oggi e valuta domani. Annota separatamente una prova utile e il compito reale. Se continui a prepararti senza tentare, accorcia la preparazione o scegli un’altra occasione disponibile. Questa sequenza dalla scena al tentativo è un adattamento ODA, non un protocollo convalidato dalla meta-analisi."]}],sources:["manifest-P05","manifest-T04","manifest-T17"]},{number:11,technique:"Metodo 55x5",title:"55x5: tante righe, candidatura ancora vuota?",goal:"Affianca alla scrittura facoltativa un’azione fattibile da verificare.",hook:"Hai scritto cinquantacinque righe, candidatura ancora vuota? Scrivi la prossima frase utile dove serve.",reason:"Quanto puoi dedicare alla scrittura senza togliere tempo al lavoro utile?",paragraphs:["Il 55x5 prevede di scrivere un’affermazione al presente 55 volte al giorno per cinque giorni. Scegli un risultato e ripeti la stessa frase fino al conteggio. Non supportato: che numero o durata attirino il risultato. Alcuni esperimenti sui sogni a occhi aperti idealizzati hanno ridotto l’energia immediata; non dimostrano che immaginare o praticare questo rito ostacoli sempre l’impegno.","Versione ODA: scrivi se ti piace; le ripetizioni sono facoltative. Scegli un obiettivo preciso e un passo fattibile ogni giorno. Individua l’ostacolo e decidi cosa fare se si presenta, in un momento riconoscibile. Agisci oggi prima di scrivere ancora; domani verifica il lavoro. La ricerca sostiene i piani specifici, non questa sequenza di ripetizioni."],example:{title:"Simone lascia tempo alla candidatura",text:"A Simone piace ricopiare «Preparo candidature utili», ma le 55 righe occupano tutta la pausa. Ne tiene poche e riserva cinque minuti dopo pranzo alla candidatura. Se manca un dettaglio, scriverà una domanda ai selezionatori. Oggi invia la domanda. Annota quella richiesta: non ha ancora inviato una candidatura né ricevuto un’offerta."},instructions:["Scegli un obiettivo; riserva tempo per agire prima di decidere quante ripetizioni fare.","Scegli un momento riconoscibile e decidi cosa farai se incontri un ostacolo.","Prova il passo di oggi e verificalo domani; ripetere resta facoltativo."],action:["Chiedi il dettaglio mancante","Completa una sezione della candidatura"],minimum:["Invia una domanda ai selezionatori","Salva una sezione completa"],cue:["Appena finisco di pranzare","Dopo la scrittura facoltativa"],place:["Nella bozza di email ai selezionatori","Alla scrivania per le candidature"],obstacle:"Le ripetizioni occupano tutto il tempo disponibile",fallback:["Salta le ripetizioni e fai il minimo","Riserva tempo per agire prima del quaderno"],observation:["Lavoro svolto e tempo di scrittura, separati","Quello che ho inviato o salvato"],stopRule:"Riduci o salta la scrittura se ti affatica o sottrae il tempo disponibile per agire.",scenario:"Simone ha completato due giorni di 55 ripetizioni. Nessuno dei due gli ha lasciato tempo per la candidatura. Oggi ha la stessa breve pausa.",question:"Quale cambiamento permette di provare una routine più utile?",options:[{key:"faster",text:"Scrivere più velocemente, per mantenere tutto il rito e forse iniziare la candidatura subito dopo.",feedback:"Anche scrivendo più in fretta potrebbe non restare tempo per la candidatura. I suoi appunti mostrano che le due attività competono per la pausa. Riserva prima un momento fattibile per il lavoro, poi scegli quanta scrittura facoltativa ci sta."},{key:"weekend",text:"Completare i cinque giorni di scrittura, poi dedicare più tempo alla candidatura nel fine settimana.",feedback:"Nel fine settimana potrebbe esserci tempo, ma così rimanda il lavoro per rispettare un conteggio senza prove di efficacia. Oggi ha già una piccola occasione. Prova a usarla prima di aggiungere altre ripetizioni."},{key:"reserve",text:"Riservare cinque minuti a una sezione della candidatura, ridurre o saltare le ripetizioni e verificare domani la sezione salvata.",feedback:"Così cambia la condizione che impediva il lavoro. Può mantenere la scrittura se gli piace, lasciando spazio alla candidatura. Una sezione salvata è preparazione per l’invio: non significa aver ricevuto un’offerta."}],best:"reserve",takeaway:"Lascia tempo per agire. Finire le ripetizioni non significa aver svolto il lavoro.",review:"Quale passo hai provato e quanto tempo ti ha lasciato la scrittura?",deeper:[{heading:"La ricetta delle ripetizioni per cinque giorni",paragraphs:["1. Scegli un risultato desiderato. 2. Scrivi una frase positiva come se fosse già accaduto. 3. Ricopiala 55 volte nella sessione quotidiana. 4. Ripeti la sessione per cinque giorni. 5. Mentre scrivi, torna con l’attenzione al risultato desiderato. Il conteggio preciso appartiene alla pratica proposta, non è una dose stabilita da ricerche controllate. Alcune versioni aggiungono indicazioni sulle emozioni o sulla concentrazione senza interruzioni. [manifest-P06]","Puoi mantenere questa forma di scrittura se ti piace, ma guarda quanto tempo richiede. Prima di iniziare, decidi quanto ne serve oggi al lavoro per il tuo obiettivo. Nella versione ODA puoi scrivere meno o saltare le ripetizioni. Perdere un giorno non cancella un risultato futuro. Annota la pagina completata come scrittura e la sezione della candidatura salvata come lavoro svolto. Nessuna delle due voci significa che un’azienda ti abbia fatto un’offerta."]},{heading:"Un piano funziona per come è fatto, non per le ripetizioni",paragraphs:["La meta-analisi di Gollwitzer e Sheeran sostiene l’utilità di collegare una situazione precisa a una risposta orientata all’obiettivo, in attività diverse. Non esamina 55 ripetizioni o una regola di manifestazione di cinque giorni. Kappes e Oettingen hanno trovato che alcune fantasie positive idealizzate riducevano l’energia immediata. I loro brevi esperimenti invitano alla cautela quando immaginare piacevolmente il traguardo sostituisce la preparazione; non dimostrano che ogni pensiero ottimista o frase ripetuta faccia male. [manifest-T02, manifest-T05]","ODA usa la pagina per costruire un piano pratico. Scrivi l’obiettivo, la più piccola parte utile del lavoro e il momento in cui puoi farla. Se la scrittura tende a occupare tutta la pausa, prevedi di agire prima. Se un dettaglio mancante blocca una sezione, invia una domanda precisa. Prova oggi e verifica domani: il momento è arrivato, cosa hai fatto, cosa resta? Scrittura e azione insieme sono un adattamento, senza promesse di risultati in cinque giorni."]}],sources:["manifest-P06","manifest-T02","manifest-T05"]},{number:12,technique:"Metodo dei due bicchieri",title:"Due bicchieri: versi l’acqua. E poi?",goal:"Scegli con le etichette un passo fattibile e una risposta all’ostacolo.",hook:"Versare l’acqua è la parte facile. Cosa collega la tua situazione all’etichetta che vorresti?",reason:"Cosa renderebbe possibile quel traguardo con il tempo e i mezzi che hai?",paragraphs:["Nel metodo dei due bicchieri, uno indica la situazione attuale, l’altro quella desiderata. Riempi il primo, immagini il cambiamento, versi nel secondo e bevi l’acqua. Non supportato: che l’acqua trasporti l’intenzione o cambi dimensione. La ricerca sugli obiettivi riguarda traguardi specifici, strategie e riscontri, non una spiegazione quantistica del versare acqua.","Versione ODA: tieni i bicchieri come simboli, oppure disegna due cerchi. Tra le etichette scrivi un obiettivo preciso, un ostacolo reale e un piano «se… allora…». WOOP comprende desiderio, risultato, ostacolo e piano; la ricerca sostiene mediamente questa combinazione. Prova oggi un’azione che riduca la distanza. Domani verifica cosa hai fatto, separandolo dai risultati che dipendono anche da altri."],example:{title:"Omar scrive il passo tra i bicchieri",text:"Omar etichetta i bicchieri «Portfolio incompleto» e «Pronto a candidarmi». Sul foglietto in mezzo scrive: «Salva una descrizione del progetto dopo pranzo». Se non riesce a spiegarlo, descriverà la scelta principale. Versa l’acqua, poi scrive il testo. Al portfolio manca ancora un progetto; annota cosa è cambiato."},instructions:["Etichetta la situazione attuale e il traguardo desiderato; scegli un cambiamento fattibile.","Tra le etichette scrivi il passo di oggi e cosa fare se incontri l’ostacolo.","Prova quel passo; domani verifica il lavoro che hai svolto."],action:["Scrivi una descrizione del progetto","Chiedi un requisito del corso"],minimum:["Salva una descrizione di una scelta","Invia una domanda sul corso"],cue:["Appena finisco di pranzare","Quando ripongo i bicchieri"],place:["Nel documento del portfolio","Al tavolo della cucina"],obstacle:"Il traguardo sull’etichetta richiede più risorse",fallback:["Chiedi come accedere o fare un passo minore","Descrivi una scelta del progetto con parole semplici"],observation:["Il passo tra le etichette che ho completato","Cosa resta tra le due etichette"],stopRule:"Se preferisci, usa i disegni; se scegli di bere, usa soltanto acqua potabile.",scenario:"Sul bicchiere di Omar c’è scritto «Pronto a candidarmi». Nel portfolio ha un progetto completato senza descrizione e un secondo progetto ancora incompleto.",question:"Quale passo ci sta in cinque minuti?",options:[{key:"caption",text:"Scrivere e salvare la descrizione del progetto finito, poi annotare cosa manca ancora per completare il portfolio.",feedback:"Sceglie una parte fattibile senza nascondere quello che manca. La descrizione non completa l’intero portfolio, ma domani avrà un progresso reale da esaminare, invece di dover giudicare soltanto l’intenzione."},{key:"rename",text:"Cambiare l’etichetta desiderata in «Designer assunto», per tenere presente l’ambizione più grande durante il rito.",feedback:"L’ambizione più grande può contare, ma cambiare etichetta non risolve il portfolio incompleto. Mantieni il desiderio e scegli il piccolo lavoro che puoi svolgere nei cinque minuti disponibili."},{key:"schedule",text:"Elencare tutti i lavori rimasti nel portfolio prima di scrivere la descrizione, per pianificare l’intero percorso.",feedback:"Un elenco può aiutare una verifica successiva. In questa breve pausa sa già che manca la descrizione. Completarla permette di provare un passo fattibile, invece di usare tutto il tempo per prepararsi ancora."}],best:"caption",takeaway:"Le etichette mostrano la distanza. Un passo alla tua portata può ridurla.",review:"Cosa è cambiato grazie al tuo passo e cosa separa ancora le due etichette?",deeper:[{heading:"Il rito dei due bicchieri",paragraphs:["1. Prendi due bicchieri e scrivi sul primo la tua situazione attuale. 2. Sul secondo scrivi quella desiderata. 3. Metti acqua nel primo. 4. Immagina il cambiamento mentre versi nel secondo. 5. Bevi l’acqua e riporta l’attenzione alla situazione desiderata. Alcune descrizioni della pratica parlano di salto dimensionale. Le prove esaminate non confermano questa spiegazione metafisica. [manifest-P07]","Puoi mantenere il passaggio simbolico senza considerare vera la sua spiegazione. Per l’esercizio ODA bastano i bicchieri che hai o due cerchi disegnati. Prima di versare, scrivi un’azione tra le etichette. Non dare per certa una decisione altrui ancora incerta. Una descrizione utile nel portfolio è opera tua; un’assunzione coinvolge anche un’azienda. Se bevi, usa soltanto acqua potabile. Non servono recipienti speciali né acquisti."]},{heading:"Usa la distanza per WOOP e un piano fattibile",paragraphs:["WOOP organizza desiderio, risultato desiderato, ostacolo attuale e piano. La meta-analisi sul confronto mentale abbinato ai piani «se… allora…» ha trovato un beneficio medio modesto per raggiungere gli obiettivi, con risultati variabili e indizi di distorsione dovuta alla pubblicazione selettiva. Non ha esaminato bicchieri o acqua. La teoria degli obiettivi considera anche impegno, riscontri, capacità e complessità del lavoro. Un’etichetta significativa richiede un percorso praticabile; un obiettivo difficile senza accesso o strategia non basta. [manifest-T01, manifest-T11]","ODA rende esplicito il passaggio. Scegli un lavoro preciso per il tuo obiettivo. Individua un ostacolo su cui puoi agire e controlla i limiti esterni, come attrezzatura o denaro mancanti. «Se non posso usare lo strumento, chiederò un’alternativa disponibile» può fare della richiesta di aiuto il passo da compiere. Salva il minimo e il momento iniziale, prova oggi e verifica domani. Distingui le richieste dall’aiuto ricevuto. Bicchieri simbolici e piano pratico insieme sono un adattamento, non un trattamento combinato sperimentato."]}],sources:["manifest-P07","manifest-T01","manifest-T11"]},{number:15,technique:"Diario della gratitudine",title:"Gratitudine: puoi ringraziare e restarci male",goal:"Scrivi cosa apprezzi davvero e prova un passo utile, senza negare la difficoltà.",hook:"Puoi apprezzare l’aiuto di un’amica anche se il rifiuto della candidatura fa male.",reason:"Cosa apprezzi senza nascondere quello che deve cambiare?",paragraphs:["Nel diario della gratitudine scrivi cosa apprezzi, spesso spiegando perché e rileggendo. Alcune varianti della manifestazione ringraziano la vita per eventi futuri come se fossero accaduti. Prove miste: gli interventi di gratitudine mostrano piccoli benefici medi sul benessere contro alcuni controlli, con poco vantaggio sulle alternative psicologicamente attive. I risultati sui sintomi sono modesti; la gratitudine non basta come trattamento né prova che attiri eventi futuri.","Versione ODA: descrivi un fatto reale nel diario. Scrivi l’obiettivo preciso e una difficoltà accanto alla gratitudine. Decidi cosa farai davanti all’ostacolo e scegli un passo per oggi: ringraziare chi ti aiuta o chiedere un parere mirato. Domani verifica azione ed eventuali risposte. Essere grati non significa nascondere la delusione."],example:{title:"Giulia tiene insieme i due fatti",text:"Giulia apprezza l’amica che ha controllato la candidatura e annota l’email di rifiuto. Dopo colazione chiede quale frase iniziale migliorare. Se non possono telefonarsi, il piano prevede un messaggio breve. Oggi l’amica non riesce a rispondere. Giulia annota domanda e delusione senza inventare un parere."},instructions:["Scrivi qualcosa di reale che apprezzi e perché; lascia visibile anche la difficoltà.","Scegli un passo utile per oggi e cosa fare se compare un ostacolo probabile.","Prova il passo; domani verifica cosa hai fatto e le eventuali risposte."],action:["Chiedi un parere mirato","Ringrazia per un aiuto preciso"],minimum:["Invia una domanda sulla candidatura","Invia un ringraziamento specifico"],cue:["Appena finisco di fare colazione","Quando finisco la pagina di gratitudine"],place:["Nella conversazione dei messaggi","Al tavolo della cucina"],obstacle:"Chi mi aiuta non può telefonare",fallback:["Invia una domanda breve e mirata","Trova chi può rivedere la candidatura"],observation:["Richiesta inviata ed eventuale risposta ricevuta","Gratitudine e difficoltà, annotate con sincerità"],stopRule:"Salta la gratitudine forzata; se il disagio persiste, cerca un sostegno oltre il diario.",scenario:"Giulia apprezza il sostegno dell’amica, ma sta male per il rifiuto della candidatura. L’amica si è offerta di rispondere per messaggio a una domanda mirata.",question:"Cosa può scrivere e fare in questa situazione?",options:[{key:"positive",text:"Elencare soltanto i momenti di sostegno di oggi e rimandare l’esame del rifiuto finché si sentirà più grata.",feedback:"La gratitudine può restare nella pagina, ma non richiede di rimandare un problema concreto. L’amica ha offerto un’occasione per chiedere un parere: Giulia può fare una domanda utile e ammettere che il rifiuto fa male."},{key:"both",text:"Annotare il sostegno e la delusione, poi chiedere quale frase iniziale renderebbe più chiara la prossima candidatura.",feedback:"Così la gratitudine riguarda un fatto reale e usa il sostegno disponibile. Il messaggio è una richiesta, non un parere ricevuto. Domani Giulia potrà annotare l’eventuale risposta e scegliere cosa correggere."},{key:"future",text:"Ringraziare per la prossima offerta come se fosse arrivata, poi rileggere la pagina prima di chiedere un parere.",feedback:"Questa versione rivolta al futuro è un rito di chi pratica la manifestazione, non l’intervento di gratitudine studiato nelle revisioni citate. Non prova che un’offerta sia arrivata. Un ringraziamento reale e una domanda mirata tengono la pagina legata ai fatti."}],best:"both",takeaway:"Apprezza ciò che è reale. Lascia visibili la difficoltà e il prossimo passo utile.",review:"Cosa hai apprezzato, quale passo hai provato e qualcuno ti ha risposto?",deeper:[{heading:"Il diario della gratitudine",paragraphs:["1. Apri un quaderno o lo strumento con cui scrivi di solito. 2. Nomina qualcosa che apprezzi. 3. Spiega perché conta per te. 4. Aggiungi un’altra voce se vuoi. 5. Rileggi la pagina in un momento scelto. Un racconto diretto di chi pratica il metodo descrive questa forma con motivi e rilettura. Le varianti di manifestazione possono ringraziare per un evento futuro desiderato; è un’affermazione diversa dall’apprezzare un aiuto già ricevuto. [manifest-P10]","Per ODA basta un dettaglio quotidiano: una risposta utile, uno strumento condiviso o un momento di riposo. Non serve una voce positiva per ogni problema. Se oggi contano un rifiuto, una barriera di accesso o una delusione, scrivili accanto alla gratitudine. Scegli un passo utile per il tuo obiettivo. La pagina è una riflessione; ringraziare qualcuno o inviare una richiesta sono azioni separate. Né scrivere né chiedere garantisce una risposta."]},{heading:"Piccoli benefici medi, secondo il confronto",paragraphs:["Davis e colleghi hanno trovato piccoli benefici medi sul benessere per gli interventi di gratitudine rispetto ad alcuni controlli. La gratitudine non superava le alternative psicologicamente attive sul benessere, e i risultati sull’ansia erano inconcludenti. Cregg e Cheavens hanno trovato cambiamenti medi modesti nei sintomi di depressione e ansia analizzati insieme, più grandi rispetto alle liste d’attesa che ai controlli attivi; l’analisi separata sull’ansia era inconcludente. Non emerge una dose ottimale del diario, un sollievo garantito o un trattamento sufficiente. Non studiano neppure eventi futuri che arrivano perché qualcuno ha ringraziato l’universo. [manifest-T09, manifest-T10]","ODA aggiunge un piano pratico senza chiamarlo l’intervento studiato. Mantieni l’obiettivo preciso, individua l’ostacolo attuale e decidi cosa fare se compare. Se chi ti aiuta non può telefonare, invia una domanda mirata. Prova oggi e verifica domani. Annota la richiesta separatamente dall’eventuale risposta, lasciando spazio anche alla delusione. Puoi saltare la gratitudine se ti sembra forzata e compiere comunque il passo utile o cercare sostegno."]}],sources:["manifest-P10","manifest-T09","manifest-T10"]},{number:16,technique:"Fai come se / embodiment",title:"Fai come se: prima il lavoro, poi il guardaroba",goal:"Esprimi il ruolo desiderato con un comportamento alla tua portata.",hook:"Vuoi sentirti un professionista? Prepara un esempio di lavoro prima di comprare vestiti.",reason:"Quale comportamento esprime l’obiettivo senza spendere soldi che ti servono altrove?",paragraphs:["«Fai come se», o embodiment, significa comportarti come chi ha già il risultato desiderato. Scegli il ruolo, immagini le abitudini, adotti comportamenti o simboli. Prove miste: obiettivi precisi e riscontri possono sostenere la prestazione; fingere che il risultato sia certo non ha un meccanismo di attrazione dimostrato. Nei sondaggi, credere nella manifestazione era associato ad alcuni rischi finanziari, senza dimostrare causalità.","Versione ODA: prova il ruolo con un comportamento alla tua portata e sotto il tuo controllo. Scegli obiettivo, ostacolo e cosa fare se compare. Puoi preparare un esempio utile o fare una domanda chiara. Agisci oggi e verifica domani. Comprare simboli è facoltativo; l’accordo di un’altra persona resta una sua decisione."],example:{title:"Raffaele prova il ruolo",text:"Raffaele vuole fare l’analista freelance. Pensa a una costosa sedia da ufficio, poi migliora un foglio di calcolo dimostrativo. Dopo pranzo verifica un calcolo e aggiunge una spiegazione. Se non può accedere al programma, userà uno strumento gratuito disponibile. L’esempio è più chiaro; non ha ancora un cliente."},instructions:["Scegli il ruolo desiderato e un comportamento concreto che puoi permetterti.","Decidi cosa fare se incontri un ostacolo; non promettere decisioni che spettano ad altri.","Prova quel comportamento oggi; domani verifica cosa hai fatto e speso."],action:["Migliora un esempio del tuo lavoro","Fai una domanda mirata al cliente"],minimum:["Salva un calcolo spiegato nell’esempio","Invia una domanda per chiarire il progetto"],cue:["Appena finisco di pranzare","Quando apro il file dimostrativo"],place:["Alla mia scrivania di lavoro","Nel foglio di calcolo dimostrativo"],obstacle:"Non posso accedere allo strumento previsto",fallback:["Usa uno strumento gratuito disponibile","Scrivi la spiegazione in un file di testo"],observation:["Lavoro prodotto e soldi davvero spesi","La modifica salvata nell’esempio"],stopRule:"Spendi solo ciò che puoi permetterti; non dare per certi un reddito incerto o il consenso altrui.",scenario:"Raffaele cerca lavoro freelance e non ha clienti confermati. Uno strumento a pagamento userebbe soldi riservati alle necessità; uno gratuito disponibile basta per il suo esempio.",question:"Quale azione esprime meglio quel ruolo oggi?",options:[{key:"sample",text:"Migliorare un esempio con lo strumento disponibile, annotare la modifica e proteggere i soldi per le necessità.",feedback:"Così esprime il ruolo con un comportamento sostenibile e un risultato verificabile. Non garantisce un cliente, ma migliora qualcosa che Raffaele può mostrare. I soldi per le necessità non devono finanziare un simbolo dall’esito incerto."},{key:"purchase",text:"Comprare subito lo strumento a pagamento, per avere un ambiente di lavoro coerente con il ruolo professionale desiderato.",feedback:"Uno strumento può essere utile se il lavoro lo richiede e il costo è sostenibile. Qui quello gratuito basta, mentre l’acquisto intacca i soldi per le necessità. Provare un ruolo non rende certo il reddito futuro."},{key:"wait",text:"Aspettare un cliente confermato prima di preparare un esempio, evitando così di investire impegno in un risultato incerto.",feedback:"Proteggere i soldi ha senso, ma un piccolo esempio si può creare con le risorse disponibili. Aspettare la certezza blocca anche questa prova alla sua portata. Stabilisci un limite realistico all’impegno e controlla cosa serve all’esempio."}],best:"sample",takeaway:"Prova un comportamento che puoi permetterti. Distingui ruolo, spese e risultati esterni.",review:"Quale comportamento hai provato, quanto è costato e quale risultato conosci davvero?",deeper:[{heading:"Provare il ruolo desiderato",paragraphs:["1. Scegli la situazione o il ruolo che desideri. 2. Immagina come quella persona trascorre una giornata normale. 3. Scegli comportamenti, oggetti o abitudini associati a quella vita. 4. Agisci come se il cambiamento fosse già avvenuto. 5. Osserva come ti senti e riprova se vuoi. Un racconto di chi pratica il metodo descrive vestiti e bagagli preparati come se un lavoro fosse confermato. L’offerta successiva è un aneddoto, non un confronto controllato. [manifest-P11]","ODA mantiene la prova del ruolo, ma chiede un comportamento con un costo sostenibile. Preparare un esempio di lavoro, arrivare con una scaletta o fare una domanda chiara può servire al tuo obiettivo. Non occorre possedere oggetti costosi per provare il ruolo. Non agire come se un’altra persona avesse acconsentito o un’azienda ti avesse assunto senza conferma. Un futuro possibile indica una direzione; non è una risorsa che possiedi già."]},{heading:"Gli obiettivi richiedono riscontri e risorse reali",paragraphs:["La teoria degli obiettivi descrive come traguardi precisi e impegnativi possano sostenere la prestazione, considerando impegno, riscontri, capacità e complessità del lavoro. Non dimostra che adottare un ruolo produca da solo il risultato desiderato. Dixon e colleghi hanno trovato correlazioni tra credenze sulla manifestazione e alcuni rischi finanziari e fallimenti dichiarati dai partecipanti, senza stabilire causalità. Sentirti sicuro o di successo non equivale a un reddito già ricevuto. [manifest-T11, manifest-T13]","ODA sceglie un comportamento prima di un simbolo. Nomina il risultato concreto del lavoro di oggi e il tempo o gli strumenti disponibili. Decidi cosa fare davanti a un ostacolo probabile, come l’accesso mancante al programma, e mantieni il minimo alla tua portata. Prova oggi e verifica domani. Annota separatamente il lavoro prodotto, i costi e le eventuali risposte esterne. Se un acquisto o una promessa presuppone un successo già arrivato, ripensa il percorso. Questo insieme di ruolo e azione è un adattamento: gli studi citati non lo hanno esaminato come intervento di embodiment."]}],sources:["manifest-P11","manifest-T11","manifest-T13"]},{number:17,technique:"Lettera dal tuo io futuro",title:"Io futuro: racconta anche quel martedì difficile",goal:"Metti nella lettera futura un passo fattibile per questa settimana.",hook:"Nel futuro vivi con più calma. Come hai affrontato quel martedì difficile?",reason:"Quale futuro ti spinge a fare un passo fattibile questa settimana?",paragraphs:["Immagina il tuo io futuro che scrive alla persona che sei oggi. Scegli una data futura, descrivi vita e cambiamenti, offri incoraggiamento e rileggi. Prove miste: la ricerca sul miglior sé possibile sostiene benefici medi su benessere e ottimismo, non messaggi dal futuro né obiettivi raggiunti con certezza. Include il lavoro per costruire la vita immaginata.","Versione ODA: conserva la voce, ma racconta impegno, aiuto e una giornata comune difficile. Scegli obiettivo preciso, ostacolo attuale e cosa fare se compare. Individua un passo di oggi e salva un’occasione fattibile. La ricerca sostiene piani specifici; lettera e piano sono un adattamento. Domani verifica il tentativo, non se il futuro previsto si è avverato."],example:{title:"Chiara racconta una giornata normale",text:"Chiara immagina una settimana lavorativa più regolare e scrive di chiedere le priorità quando gli impegni si sovrappongono. Oggi, appena apre la posta lavorativa, invia una domanda per chiarirle. Se la responsabile non è disponibile, userà la chat del gruppo. Nessuna risposta immediata: annota richiesta e carico di lavoro irrisolto."},instructions:["Scrivi dal tuo io futuro; includi impegno, aiuto e un ostacolo quotidiano.","Scegli il passo di oggi e un momento preciso; decidi cosa fare se incontri l’ostacolo.","Prova il minimo e domani verifica ciò che è successo."],action:["Chiedi una priorità sul lavoro","Riserva un momento fattibile per esercitarti"],minimum:["Invia una richiesta di chiarimento","Conferma un momento disponibile per esercitarti"],cue:["Quando apro la posta di lavoro","Dopo aver sparecchiato la cena"],place:["Nella chat del gruppo di lavoro","Al tavolo della cucina"],obstacle:"La persona che mi serve non è disponibile",fallback:["Usa il canale concordato del gruppo","Scegli un altro momento disponibile per esercitarti"],observation:["Richiesta inviata ed eventuale risposta ricevuta","Il momento che ho davvero confermato"],stopRule:"Se la lettera aumenta la pressione, scegli un futuro più vicino o meno impegnativo; puoi fermarti.",scenario:"La lettera futura di Chiara promette una settimana equilibrata. Oggi due lavori urgenti si sovrappongono e la responsabile ha invitato a chiedere chiarimenti nella chat del gruppo.",question:"Quale aggiunta dà alla lettera un’utilità concreta?",options:[{key:"calendar",text:"Descrivere l’intero calendario della settimana ideale prima di chiedere quale dei due lavori urgenti venga prima.",feedback:"Un calendario può orientare le scelte successive, ma da solo non risolve questo conflitto di priorità. Chiara ha già un canale per chiedere chiarimenti. Usalo e lascia visibile la domanda ancora senza risposta."},{key:"certainty",text:"Aggiungere un incoraggiamento più forte a fidarsi del futuro, poi aspettare che il carico di lavoro sembri meno pesante.",feedback:"L’incoraggiamento può aiutare, ma aspettare una sensazione diversa lascia i due lavori urgenti in competizione. Una breve richiesta di chiarimento è già fattibile. La lettera dovrebbe aiutarla a farla senza prevedere la risposta."},{key:"request",text:"Raccontare di chiedere le priorità nei giorni difficili, poi inviare una domanda di chiarimento nella chat concordata del gruppo.",feedback:"Così nella scena futura compare un comportamento adatto all’ostacolo attuale. Inviare è un’azione sua; la risposta resta sconosciuta finché non arriva. Domani può verificare la richiesta e scegliere il prossimo passo."}],best:"request",takeaway:"La voce futura può indicare il lavoro di oggi e l’aiuto che potrebbe servirti.",review:"Quale passo della lettera hai provato e quali aiuti o risultati restano sconosciuti?",deeper:[{heading:"La forma della lettera",paragraphs:["1. Scegli un momento futuro della tua vita. 2. Immagina di essere te a quel punto. 3. Rivolgi una lettera alla persona che sei oggi. 4. Descrivi cosa è cambiato e come vivi le giornate. 5. Offri incoraggiamento o consigli, poi rileggi. Una risorsa di chi pratica il metodo documenta questa voce dal futuro al presente e il tono comprensivo. Date e saluti sono scelte di forma, non ingredienti scientificamente necessari. [manifest-P12]","Per ODA scrivi di un futuro desiderato senza chiamarlo un messaggio o una previsione. Includi una difficoltà quotidiana, l’impegno necessario e l’aiuto che potrebbe servirti. Una settimana più calma può richiedere una conversazione sulle priorità, anziché più certezza. Collega la direzione all’esperimento del corso. Sottolinea un passo fattibile per chi si sveglierà domani con le stesse risorse reali. Puoi scrivere dal futuro vicino se quello lontano ti pesa."]},{heading:"Una pagina di speranza deve riportarti a oggi",paragraphs:["La meta-analisi sul miglior sé possibile ha trovato benefici medi su benessere, ottimismo ed emozioni positive rispetto ai controlli. I partecipanti erano spesso giovani studenti e nessuno studio soddisfaceva tutti i criteri di qualità. Nell’esercizio immagini il futuro e il lavoro svolto per raggiungerlo; i risultati non dimostrano che le lettere prevedano o producano eventi esterni. Separatamente, la ricerca sui piani «se… allora…» sostiene un momento specifico collegato a una risposta fattibile. Nessuna delle due fonti ha esaminato questo preciso insieme di lettera e piano. [manifest-T08, manifest-T02]","ODA usa la lettera per scegliere un passo. Nomina un obiettivo preciso, individua l’ostacolo più vicino al lavoro di oggi e scrivi «Se succede, farò…» con una risposta fattibile. Salva momento, luogo e minimo, poi prova oggi o nell’occasione successiva scelta. Domani verifica i fatti: una richiesta, un lavoro, un ritardo o una pausa. Se qualcuno non ha risposto, lascia la risposta sconosciuta. Modifica il prossimo passo senza fingere che il futuro immaginato sia già una prova."]}],sources:["manifest-P12","manifest-T08","manifest-T02"]},{number:13,technique:"Metodo del cuscino",title:"Metodo del cuscino: un compito per il mattino",goal:"Tieni il biglietto della sera e collegalo a un'azione da fare da sveglio.",hook:"Il desiderio sotto il cuscino è ancora lì? Dai al biglietto un compito concreto per domani mattina.",reason:"Se pianificassi di giorno, avrei più spazio per dormire?",paragraphs:["Il metodo del cuscino mette un desiderio scritto sotto il cuscino. Una versione comune propone di scriverlo come già realizzato, piegare il foglio, infilarlo sotto, poi ripetere la frase o immaginare il risultato prima di dormire. Le prove esaminate non sostengono che il foglio produca risultati esterni. [manifest-P08, manifest-T19]","Versione ODA: tieni il biglietto, aggiungi obiettivo preciso e ostacolo probabile. Scrivi un piano «se... allora...» per un'azione. La ricerca sostiene questi piani concreti; non un particolare potere di attrazione prima del sonno. Fai qualcosa di utile oggi, valuta domani. Se pianificare ti tiene sveglio, continua di giorno. [manifest-T02, manifest-T19]"],example:{title:"Un messaggio al mattino",text:"Al tavolo della cucina, Marta scrive il desiderio di trovare lavoro e invia una candidatura mirata. Sul biglietto aggiunge: quando avrò sparecchiato la colazione, controllerò un nuovo annuncio adatto. Il mattino dopo lo controlla e comincia un'altra candidatura. Mancano alcuni dettagli. Annota separatamente la candidatura inviata e la bozza incompleta; nessun datore di lavoro ha risposto."},instructions:["Tieni il biglietto; aggiungi obiettivo e ostacolo prima di prepararti a dormire.","Scrivi un piano «se... allora...» e fai un'azione utile oggi.","Domani valuta l'azione tentata separatamente dal rituale del cuscino."],action:["Invia una candidatura mirata","Chiedi a un contatto di un posto disponibile"],minimum:["Invia una candidatura adatta","Manda una domanda precisa"],cue:["Dopo aver sparecchiato la colazione","Dopo la pausa pranzo di oggi"],place:["Al tavolo della cucina","Dove lavoro di solito"],obstacle:"Pianificare prima di dormire mi tiene sveglio",fallback:["Pianifica nella pausa pranzo di domani","Usa un biglietto durante il giorno"],observation:["Candidatura inviata; risposta ancora sconosciuta","Domanda inviata; risposta annotata a parte"],stopRule:"Fermati se il rituale ritarda il sonno. Pianifica di giorno; non devi ripetere nulla prima di dormire.",scenario:"Sul biglietto Marta ha scritto una domanda da fare al mattino su un posto adatto a lei. Riscriverlo prima di dormire la tiene sveglia, anche se il momento scelto per domani è già chiaro.",question:"Che cosa dovrebbe fare stasera?",options:[{key:"a",text:"Riscrivere il biglietto ancora una volta e decidere domani se quella domanda le sembra ancora giusta.",feedback:"Riscriverlo le toglie sonno senza aggiungere un dettaglio necessario. Sa già quando agire. Può mantenere la domanda prevista e rimandare al giorno qualsiasi altra modifica al biglietto."},{key:"b",text:"Lasciare stare il biglietto, dormire e chiedere del posto nel momento scelto per il mattino.",feedback:"Così protegge il sonno e mantiene l'impegno utile. Domani potrà annotare se ha inviato la domanda, tenendo separata dalla propria azione l'eventuale risposta del datore di lavoro."},{key:"c",text:"Sostituire la domanda del mattino con una visualizzazione più lunga, di giorno, della risposta del datore di lavoro.",feedback:"Di giorno può dedicare più tempo a pianificare, ma qui rinuncia a un'azione utile già possibile. Immaginare una risposta non invia il messaggio e non dice che cosa deciderà il datore di lavoro."}],best:"b",takeaway:"Tieni breve il biglietto sotto il cuscino e scegli quando agire da sveglio.",review:"Quale azione hai tentato dopo il biglietto? Pianificare prima di dormire ha disturbato il sonno?",deeper:[{heading:"Come si fa il rituale del cuscino",paragraphs:["1. Scegli un risultato desiderato e scrivi una frase al presente, per esempio un'offerta di lavoro immaginata come già ricevuta. Segui così le indicazioni di chi pratica il metodo. La frase esprime un desiderio, non una notizia verificata. Puoi tenerla per te. [manifest-P08]","2. Piega il foglio e mettilo sotto il cuscino. La guida aggiunge dettagli su come scrivere e piegare, ma appartengono alla versione di quell'autrice. Non sono requisiti dimostrati per ottenere un risultato esterno. Usa un normale foglietto che hai già in casa. [manifest-P08]","3. Leggi o ripeti mentalmente la frase mentre ti sistemi a letto. Se ti piace, immagina il desiderio realizzato. Poi lasciati dormire. Per smettere non devi raggiungere immagini nitide, un certo numero di ripetizioni o una particolare sensazione. [manifest-P08]","4. Se vuoi, riprendi il biglietto un'altra sera. La guida documenta un rituale riconoscibile, non prove controllate di efficacia. Una rassegna sui circuiti della veglia non dimostra che i desideri prima del sonno aggirino il pensiero critico o facciano accadere eventi esterni. [manifest-P08, manifest-T19]"]},{heading:"Un biglietto che ti serve da sveglio",paragraphs:["Prima di andare a letto, aggiungi una piccola istruzione pratica. Scrivi l'obiettivo preciso, l'ostacolo che prevedi e l'azione che puoi fare. Per cercare lavoro: «Quando avrò sparecchiato la colazione, invierò una candidatura adatta. Se il modulo non è chiaro, farò una domanda precisa a chi seleziona il personale». Tieni separati dall'azione i risultati incerti, come ricevere un'offerta. [manifest-T02]","La meta-analisi di Gollwitzer e Sheeran ha rilevato un beneficio medio nel raggiungere gli obiettivi con piani precisi «se... allora...», in contesti diversi. Non ha studiato fogli sotto i cuscini né dimostrato che pianificare elimini la fatica. La rassegna sulla veglia descrive circuiti che interagiscono, non una via subconscia per esaudire desideri. Sono affermazioni diverse. [manifest-T02, manifest-T19]","ODA aggiunge il tentativo di oggi e la verifica di domani come scelte pratiche, non come una procedura serale già sperimentata. Annota ciò che hai inviato, chiesto o completato; separa le eventuali risposte. Se modificare il biglietto ti tiene sveglio, lascialo stare e scegli un momento di giorno. Per fare qualcosa di utile non devi completare il rituale. [manifest-T02, manifest-P08]"]}],sources:["manifest-P08","manifest-T02","manifest-T19"]},{number:14,technique:"Metodo del sussurro",title:"Metodo del sussurro: prova una richiesta che puoi fare",goal:"Trasforma una conversazione immaginata in una richiesta rispettosa che dipende da te.",hook:"Aspetti una risposta a un messaggio? Il rituale del sussurro può aiutarti a scegliere il tuo prossimo passo.",reason:"C'è una richiesta che posso fare senza essere invadente?",paragraphs:["Nel metodo del sussurro immagini una richiesta a un'altra persona. Una versione comune: rilassati, immagina di avvicinarti, sussurra tre volte ciò che vuoi e poi esci dalla scena. Le prove esaminate non sostengono che questo faccia rispondere la persona a distanza. Consenso e limiti restano validi. [manifest-P09]","Versione ODA: tieni il sussurro privato, scegli un obiettivo preciso e indica l'ostacolo. Prova una richiesta rispettosa che lasci spazio a un no. Scrivi un piano «se... allora...» per un'azione appropriata oggi, valuta il tentativo domani. La ricerca sostiene la pianificazione concreta; la tua certezza sulla risposta altrui non dimostra che quella persona acconsentirà. [manifest-T02, manifest-T13]"],example:{title:"Chiedere senza insistere",text:"A pranzo, Marco immagina di sussurrare una richiesta per un incontro sul progetto. La trasforma in una frase da inviare: «Possiamo parlarne per dieci minuti giovedì?». La collega risponde che giovedì è pieno. Marco annota messaggio e rifiuto, poi chiede se va bene la settimana successiva. Il rituale non la obbligava ad accettare."},instructions:["Sussurra una richiesta rispettosa in privato; lascia alla persona la possibilità di dire no.","Indica obiettivo, ostacolo e piano «se... allora...»; fai una richiesta appropriata oggi.","Domani valuta che cosa hai chiesto e come hai rispettato la risposta."],action:["Chiedi un breve incontro sul progetto","Manda una domanda appropriata sulla disponibilità"],minimum:["Invia una richiesta d'incontro chiara","Fai una domanda pertinente"],cue:["Dopo la pausa pranzo di oggi","Quando inizia il confronto concordato"],place:["Alla mia scrivania al lavoro","Dove ci riuniamo di solito"],obstacle:"Continuo a modificare una richiesta semplice",fallback:["Usa una sola frase diretta","Chiedi durante il confronto concordato"],observation:["Richiesta fatta; risposta annotata a parte","Limite rispettato; prossimo passo scelto"],stopRule:"Non contattare chi ha detto di non voler essere contattato. Le immagini private non possono scavalcare i limiti di un'altra persona.",scenario:"Marco vuole un incontro. La collega ha detto che questa settimana è piena, ma lo ha invitato a chiedere per la prossima. Il sussurro immaginato lo rassicura.",question:"Quale passo è adatto alle informazioni che ha?",options:[{key:"a",text:"Chiedere una volta la disponibilità per la prossima settimana e accettare la risposta senza mandare altri messaggi.",feedback:"È stata lei a offrirgli questa possibilità: una domanda chiara la rispetta. Marco può annotare separatamente richiesta e risposta. Sentirsi rassicurato non gli dà alcun diritto sul tempo della collega."},{key:"b",text:"Aspettare che lei proponga un orario, perché la conversazione immaginata ormai gli sembra completa.",feedback:"Può scegliere di aspettare, ma la conversazione immaginata non ha chiesto nulla per la prossima settimana. L'invito della collega gli offre un'occasione adatta per una richiesta reale, se l'incontro gli serve ancora."},{key:"c",text:"Inviare un messaggio più sentito per spiegare quanto significherebbe per lui incontrarsi questa settimana.",feedback:"Anche un messaggio più sentito le chiede di ripensare alla settimana che ha escluso. Può usare la possibilità che lei ha offerto, senza trasformare sentimenti più forti in un motivo per insistere."}],best:"a",takeaway:"Prova la richiesta; la risposta resta una scelta altrui.",review:"Quale richiesta hai fatto davvero? Come hai reagito alla risposta o al limite che la persona ha posto?",deeper:[{heading:"La conversazione immaginata del rituale",paragraphs:["1. Scegli la persona e la risposta desiderata. Nel racconto di chi pratica il metodo, l'esercizio avviene nell'immaginazione. Scegliere una risposta dice che cosa vuoi tu; non dice che cosa vuole quella persona e non ti dà il permesso di contattarla. [manifest-P09]","2. Rilassati e immagina quella persona in un luogo. Immagina di avvicinarti e sussurrarle la richiesta all'orecchio tre volte. Quel numero fa parte della ricetta, non è una dose scientificamente dimostrata per influenzare qualcuno. Puoi adattare l'esercizio tenendo gli occhi aperti o descrivendo la scena a parole. [manifest-P09]","3. Esci dalla scena immaginata. Alcune varianti aggiungono un bacio sulla fronte: è un altro dettaglio della scena, non una prova d'influenza a distanza. In ODA, tieni l'esercizio privato e scegli una richiesta che potresti fare con rispetto. L'intimità immaginata non equivale al consenso. [manifest-P09]","4. Decidi se una richiesta reale è appropriata. Il racconto documenta il rituale, ma non può dimostrare telepatia o controllo. Una persona può rifiutare, non rispondere o cambiare idea. Ripetere i sussurri non crea alcun obbligo di risponderti. [manifest-P09]"]},{heading:"Pianifica la tua parte della conversazione",paragraphs:["Mantieni l'obiettivo preciso: chiedere un incontro quando la persona è disponibile è diverso dal farle provare ammirazione per te. Indica un ostacolo che puoi affrontare, come rimandare un breve messaggio a forza di correggerlo. Poi scegli quando agire: «Finita la pausa pranzo, invierò una domanda chiara sulla disponibilità». Se il contatto non è gradito, la tua azione può essere rispettare quel limite. [manifest-T02, manifest-P09]","La ricerca sulle intenzioni di implementazione sostiene i piani che collegano una situazione riconoscibile a un'azione scelta. Non dimostra controllo su chi riceve la richiesta. In tre campioni di un'indagine online, Dixon e colleghi hanno trovato un'associazione tra credere nella manifestazione, fiducia e alcuni rischi finanziari riferiti. Le associazioni non dimostrano causalità; lo studio non ha testato i sussurri. La tua certezza non misura il consenso altrui. [manifest-T02, manifest-T13]","La prova privata e la verifica del giorno dopo sono adattamenti ODA. Fai una richiesta appropriata oggi o scegli un'occasione concordata. Domani scrivi che cosa hai chiesto davvero, l'eventuale risposta e se l'hai rispettata. Il silenzio resta un dato incerto. Scegli un altro passo appropriato oppure fermati; la conversazione immaginata non conta come conversazione reale. [manifest-T02, manifest-P09]"]}],sources:["manifest-P09","manifest-T02","manifest-T13"]},{number:18,technique:"Concentrazione di 17 secondi",title:"17 secondi di concentrazione: al suono del timer, agisci",goal:"Usa una pausa che ti piace per iniziare, senza attribuire alla durata un valore scientifico.",hook:"Ti sei distratto prima dei diciassette secondi? Puoi comunque fare il prossimo passo, senza ricominciare.",reason:"Il timer mi aiuta a iniziare o mi fa rimandare?",paragraphs:["Nel metodo dei 17 secondi mantieni un pensiero desiderato senza contraddirlo per diciassette secondi. Alcune versioni ripetono quattro intervalli: sessantotto secondi totali. Le prove esaminate non sostengono durate speciali né soglie di attrazione. La ricerca sul priming non convalida questi numeri o i rituali intenzionali sui desideri. [manifest-P13, manifest-T16]","Versione ODA: usa diciassette secondi come pausa preferita, poi indica obiettivo preciso e ostacolo. Scrivi un piano «se... allora...» per un'azione oggi e valuta il tentativo domani. La ricerca sostiene i piani concreti. Se ti distrai, non devi ricominciare: il timer indica quando partire, non è un requisito per ottenere risultati. [manifest-T02, manifest-P13]"],example:{title:"Una pausa interrotta",text:"Prima di pranzo, Giulia imposta un timer di diciassette secondi per il portfolio. Una consegna la distrae. Lascia stare il timer e segue il piano: dopo pranzo, mandare un esempio di lavoro a un cliente adatto. Il cliente chiede uno stile diverso. Giulia annota messaggio e riscontro, senza ricominciare l'esercizio di concentrazione."},instructions:["Scegli l'obiettivo; usa diciassette secondi come pausa facoltativa.","Indica un ostacolo e un piano «se... allora...»; fai un'azione utile oggi.","Domani valuta l'azione tentata, compresi gli eventuali riscontri ricevuti."],action:["Invia un esempio di lavoro pertinente","Chiedi un riscontro su una bozza"],minimum:["Manda un esempio adatto","Fai una domanda precisa per un riscontro"],cue:["Dopo il pranzo di oggi","Quando finisce il timer facoltativo"],place:["Dove lavoro di solito","Al tavolo della biblioteca"],obstacle:"Ricomincio ogni volta che mi distraggo",fallback:["Salta il timer e invia","Scrivi quando iniziare l'azione"],observation:["Esempio inviato; risposta annotata a parte","Domanda fatta; riscontro ancora sconosciuto"],stopRule:"Salta il timer se ricominciare ritarda l'azione o ti crea disagio. I pensieri indesiderati non richiedono correzioni rituali.",scenario:"L'esempio preparato da Giulia risponde alla richiesta di un cliente. Una notifica ha interrotto il timer di concentrazione. Ha cinque minuti per inviarlo prima di una riunione.",question:"Come può usare al meglio questa occasione?",options:[{key:"a",text:"Ripetere la concentrazione una volta senza notifiche, poi inviare se resta tempo prima della riunione.",feedback:"Togliere le notifiche può aiutare durante una pausa che le piace, ma il compito è già chiaro. Pretendere un altro intervallo senza interruzioni rischia di farle perdere l'occasione utile che ha adesso."},{key:"b",text:"Rimandare esercizio di concentrazione e invio a domani, per avere una sessione più lunga e senza interruzioni.",feedback:"Un appuntamento successivo può servire per un compito più lungo. Qui l'esempio è pronto e ci sono cinque minuti: l'interruzione del rituale non richiede di rimandare il messaggio."},{key:"c",text:"Inviare subito l'esempio pronto e annotare il messaggio separatamente dalla pausa di concentrazione interrotta.",feedback:"Così usa l'occasione disponibile e descrive fedelmente ciò che è successo. L'esempio è stato inviato; la pausa è stata interrotta. Nessuno dei due fatti dice che cosa deciderà il cliente."}],best:"c",takeaway:"Usa il timer per sapere quando agire, senza farne una condizione da rispettare.",review:"Quale azione utile hai tentato? Il timer ti ha aiutato a iniziare o ti ha fatto rimandare?",deeper:[{heading:"Che cosa prevede il metodo dei diciassette secondi",paragraphs:["1. Scegli un'esperienza desiderata o un pensiero positivo. L'insegnamento attribuito ad Abraham attraverso Esther e Jerry Hicks chiede di concentrarsi su quel pensiero senza pensarne uno contrario. Questo descrive il rituale, non una procedura sottoposta a verifica nella ricerca. [manifest-P13]","2. Mantieni il pensiero per diciassette secondi. Alcune versioni continuano per quattro intervalli consecutivi, arrivando a sessantotto secondi. Puoi usare un timer per mantenere il formato riconoscibile, ma le prove esaminate non dimostrano una soglia speciale di attrazione per nessuna delle due durate. [manifest-P13, manifest-T16]","3. Nota se ti sei distratto, senza trasformarlo in un verdetto sul tuo futuro. In ODA non devi ricominciare per poter agire. Le affermazioni del maestro secondo cui i pensieri cambierebbero la realtà o varrebbero molte ore di lavoro non sono risultati della ricerca esaminata. [manifest-P13]","4. Termina la pausa e scegli il prossimo gesto. Il priming sperimentale riguarda stimoli studiati in condizioni specifiche; non coincide con questo desiderio intenzionale a tempo. La durata che preferisci può restare parte del rituale senza acquisire per questo autorità scientifica. [manifest-T16, manifest-P13]"]},{heading:"Quando il timer finisce, comincia",paragraphs:["Scegli un'azione prima di avviare il timer. Per il portfolio, potrebbe essere inviare oggi un esempio di lavoro adatto. Indica l'ostacolo: ricominciare finché la concentrazione non sembra perfetta. Poi scrivi: «Quando finisce il timer, invierò l'esempio pronto, anche se mi sono distratto». Se il timer ti mette pressione, scegli un altro segnale visibile che ti ricordi quando agire. [manifest-T02]","La meta-analisi di Gollwitzer e Sheeran sostiene in media i piani precisi «se... allora...» per compiti diversi. La rassegna di Dai e colleghi sul priming ha trovato un effetto medio complessivo, ma effetti minori e statisticamente inconcludenti nel limitato sottoinsieme preregistrato. L'incertezza non smentisce tutto il priming. Nessuna delle due rassegne convalida diciassette secondi, sessantotto secondi o una regola secondo cui i pensieri indesiderati bloccano i risultati. [manifest-T02, manifest-T16]","La sequenza ODA di pausa e azione è un adattamento, non coincide con nessuno dei due protocolli di ricerca. Domani annota l'azione tentata e i riscontri esterni, separandoli dalla qualità della concentrazione. La pausa ti ha dato un buon momento per iniziare o i nuovi tentativi hanno consumato l'occasione? In base a ciò che è successo, tieni, accorcia o elimina il timer. [manifest-T02, manifest-P13]"]}],sources:["manifest-P13","manifest-T02","manifest-T16"]},{number:19,technique:"Scatola dei desideri",title:"Scatola dei desideri: scegli quando agire su un biglietto",goal:"Tieni la scatola e fai un passo possibile verso un obiettivo preciso.",hook:"La scatola è piena di desideri. Per quale biglietto farai qualcosa oggi?",reason:"Quale desiderio è alla portata del mio tempo e delle mie risorse oggi?",paragraphs:["Il metodo della scatola raccoglie desideri scritti, immagini o oggetti significativi in un contenitore. Una versione comune: scegli una scatola, aggiungi intenzioni e sensazioni desiderate, poi rivedi il contenuto immaginando i desideri realizzati. Le prove esaminate non sostengono che il contenitore li esaudisca. Basta una scatola che hai già. [manifest-P14]","Versione ODA: tieni i biglietti. Su uno, aggiungi obiettivo preciso, ostacolo, piano «se... allora...» e un'azione per oggi; domani valuta il tentativo. La ricerca sostiene il confronto tra obiettivo e ostacoli con un piano per affrontarli, e in media il monitoraggio dei progressi. Questo adattamento della scatola non è stato testato. [manifest-T01, manifest-T03]"],example:{title:"Un biglietto esce dalla scatola",text:"Al tavolo della cucina, Luca mette in una vecchia scatola di scarpe un biglietto per un corso nel fine settimana. Scrive l'ostacolo, il poco tempo, e chiama l'organizzatore per chiedere le modalità di frequenza. Non ci sono opzioni flessibili. Domani annota la chiamata e sceglie un altro corso, invece di aggiungere desideri alla scatola."},instructions:["Scegli un contenitore che hai già e un biglietto con un obiettivo preciso.","Aggiungi un ostacolo e un piano «se... allora...»; fai un'azione possibile oggi.","Domani riapri quel biglietto e annota l'azione che hai tentato davvero."],action:["Chiedi le modalità di frequenza del corso","Richiedi un dettaglio pertinente sul programma"],minimum:["Manda una domanda precisa sul corso","Fai una richiesta di informazioni utile"],cue:["Dopo la colazione di oggi","Quando apre il centralino dell'ufficio"],place:["Al tavolo della cucina","Nel mio angolo di lavoro tranquillo"],obstacle:"Gli orari potrebbero non andare bene",fallback:["Chiedi un'altra modalità di frequenza","Contatta un'alternativa adatta"],observation:["Domanda inviata; risposta sugli orari annotata","Alternativa contattata; risposta ancora sconosciuta"],stopRule:"Usa materiali che hai già. Se un'opzione supera le tue risorse, cambia azione o fai una pausa.",scenario:"Sul biglietto del corso, Luca ha scritto un problema di orari. Oggi l'organizzatore può rispondere alle domande. Luca ha anche diverse nuove immagini da aggiungere alla scatola.",question:"Quale passo verifica meglio se questo corso fa per lui?",options:[{key:"a",text:"Chiedere all'organizzatore le modalità di frequenza e scrivere la risposta sul biglietto del corso.",feedback:"Così verifica l'ostacolo indicato e annota un fatto concreto. La risposta potrebbe escludere questo corso, ma aiuterebbe comunque Luca a scegliere un prossimo passo possibile."},{key:"b",text:"Aggiungere prima le nuove immagini, così la scatola rappresenta tutta l'esperienza che desidera.",feedback:"Le immagini possono restare parte del rituale che preferisce, ma non rispondono alla domanda sugli orari. L'occasione di oggi gli permette di capire se il corso è fattibile."},{key:"c",text:"Scegliere subito un altro corso, visto che il problema di orari rende questo incerto.",feedback:"Un altro corso potrebbe andare meglio, ma ora l'organizzatore può chiarire il dubbio. Una domanda precisa dà a Luca informazioni utili prima di decidere se cambiare obiettivo."}],best:"a",takeaway:"Tieni il biglietto, aggiungi un'azione possibile e annota che cosa è successo davvero.",review:"Quale azione hai tentato per quel biglietto? Che cosa hai scoperto sull'ostacolo?",deeper:[{heading:"Prepara la scatola dei desideri",paragraphs:["1. Scegli una scatola o un contenitore. La guida di chi pratica il metodo usa la scatola per raccogliere intenzioni. ODA ti chiede di usare qualcosa che hai già, come una vecchia scatola di scarpe o una busta. Non devi comprare un oggetto speciale per questo esercizio. [manifest-P14]","2. Scrivi i desideri su biglietti o scegli immagini che li rappresentino. La guida include anche perché desideri ogni risultato e come ti sentiresti ricevendolo. Se preferisci, tieni privati questi dettagli personali; puoi conservare il formato usando una semplice etichetta. [manifest-P14]","3. Metti i biglietti o le immagini all'interno. Riprendi il contenuto e immagina di ricevere ciò che desideri, se quel rituale ti piace. Questi passaggi descrivono il metodo raccontato da una praticante, non dimostrano che il contenitore produca un evento nel mondo esterno. [manifest-P14]","4. Scegli un biglietto da collegare a un'occasione reale. La spiegazione della guida sui campi energetici è una credenza, non un risultato scientifico dimostrato. Puoi tenere il contenitore simbolico e cambiare ciò che fai oggi con un biglietto. [manifest-P14]"]},{heading:"Scrivi l'ostacolo sul retro",paragraphs:["Tieni il desiderio o l'immagine davanti. Sul retro scrivi l'obiettivo preciso, un ostacolo probabile e un piano «se... allora...». Per un corso: «Quando apre il centralino dell'organizzatore, chiederò le modalità di frequenza. Se gli orari non vanno bene, mi informerò su un'alternativa adatta». Scegli un'azione possibile oggi: preparare il biglietto non equivale a chiedere informazioni sul corso. [manifest-T01]","Il contrasto mentale con intenzioni di implementazione collega un risultato desiderato, un ostacolo reale e un piano per affrontarlo. La meta-analisi ha trovato un sostegno medio modesto al raggiungimento degli obiettivi, con risultati variabili e possibile distorsione di pubblicazione. Harkin e colleghi hanno trovato benefici medi nell'incoraggiare il monitoraggio dei progressi. Nessuna rassegna ha testato una scatola di manifestazione o dimostrato che il giorno dopo sia il momento migliore per valutare. [manifest-T01, manifest-T03]","La verifica del giorno dopo proposta da ODA dà al biglietto un uso pratico. Annota ciò che hai chiesto davvero e ciò che hai scoperto; distingui una domanda inviata da una risposta utile o dall'iscrizione. Cambia obiettivo se mancano soldi, tempo o possibilità di accesso. La scatola può contenere un biglietto rivisto, un obiettivo sospeso o il resoconto sincero di un tentativo non riuscito. [manifest-T01, manifest-T03]"]}],sources:["manifest-P14","manifest-T01","manifest-T03"]},{number:20,technique:"SATS: stato simile al sonno",title:"SATS: lascia finire la scena e dormi",goal:"Immagina con calma e prova un passo pratico senza ritardare il sonno.",hook:"Ripeti la scena perfetta prima di dormire? Puoi fermarti e fare comunque un passo utile domani.",reason:"Questa scena mi lascia abbastanza spazio per dormire?",paragraphs:["SATS, stato simile al sonno, significa immaginare una breve scena del desiderio realizzato mentre sei rilassato e assonnato. I praticanti scelgono una scena di successo, vi partecipano nell'immaginazione e la ripetono come reale. Alcuni si addormentano. Verdetto: prove miste per immagini mentali affini; non sostengono che il dormiveglia esaudisca desideri. La simulazione mentale favorisce mediamente il comportamento, senza vantaggi specifici dimostrati prima del sonno. [manifest-P15, manifest-T04, manifest-T19]","Versione ODA: immagina con calma. Scrivi obiettivo preciso, ostacolo e piano «se... allora...». Prova il primo passo pratico. Fai un'azione oggi e valuta domani. La scena può essere imperfetta. Fermati se ripeterla ti tiene sveglio: dormire non è una prova di quanto ci credi. [manifest-P15, manifest-T19]"],example:{title:"Una scena con un limite",text:"Nina invia una domanda su un corso di formazione. Prima di dormire immagina brevemente di frequentarlo, e prova a chiedere i costi nella pausa pranzo di domani. La ripetizione la tiene vigile: si ferma. Il giorno dopo chiede: costa troppo. Annota la risposta e cerca un'opzione gratuita."},instructions:["Prima di dormire, scrivi obiettivo, ostacolo e piano «se... allora...» su un biglietto.","Prova brevemente il primo passo; fai un'azione utile oggi.","Dai la precedenza al sonno; domani valuta l'azione che hai tentato davvero."],action:["Chiedi i costi di un corso","Chiedi come accedere al corso"],minimum:["Manda una domanda sui costi","Fai una domanda sull'accesso al corso"],cue:["Dopo la pausa pranzo di oggi","Quando apre l'ufficio del corso"],place:["Dove lavoro di solito","Al tavolo della cucina"],obstacle:"Le immagini mi tengono sveglio",fallback:["Prova a parole durante il giorno","Salta le immagini e chiedi direttamente"],observation:["Domanda fatta; risposta annotata a parte","Sonno disturbato; visualizzazione interrotta"],stopRule:"Fermati se le immagini ti tengono più sveglio o creano disagio. Prova di giorno oppure evita l'esercizio; proteggi il sonno.",scenario:"Nina ha un piano chiaro per chiedere i costi di giorno. Ripetere la scena SATS la tiene vigile e la scena non le sembra ancora del tutto reale.",question:"Che cosa dovrebbe scegliere adesso?",options:[{key:"a",text:"Semplificare la scena e continuare a ripeterla finché non sembra abbastanza convincente da poter smettere.",feedback:"Semplificare può andare bene per una prova di giorno, ma sentirsi convinta non è un requisito per smettere. Ripetere la tiene vigile: continuare mette il rituale davanti al sonno."},{key:"b",text:"Interrompere la scena, dormire e chiedere i costi nel momento scelto per il giorno.",feedback:"Sa già quando fare la domanda concreta. Fermarsi protegge il sonno senza abbandonare l'obiettivo. Domani potrà annotare la domanda fatta e le eventuali informazioni ricevute sui costi."},{key:"c",text:"Sostituire la domanda sui costi con una sessione SATS più lunga di giorno, che sembra più facile da controllare.",feedback:"Di giorno può trovare più spazio per immagini facoltative, ma una scena più lunga non risponde alla domanda sui costi. Mantieni la richiesta reale e considera ogni prova come preparazione."}],best:"b",takeaway:"Puoi finire una breve scena prima che sembri perfetta; annota il tentativo reale a parte.",review:"Quale azione hai tentato davvero? Le immagini hanno lasciato spazio al sonno?",deeper:[{heading:"La scena nell'insegnamento SATS",paragraphs:["1. Scegli un risultato e una breve scena che faccia capire che è già accaduto. Le lezioni di Neville Goddard descrivono la partecipazione a una scena del desiderio realizzato, anziché guardarti dall'esterno. È il metodo del maestro, non una via dimostrata per cambiare gli eventi esterni. [manifest-P15]","2. Siediti o sdraiati comodo, chiudi gli occhi se vuoi e rilassati verso il dormiveglia. La fonte considera questo stato parte della pratica. ODA permette di adattarla tenendo gli occhi aperti o usando parole e non ti chiede di forzare la sonnolenza. [manifest-P15]","3. Ripeti la breve scena immaginandola reale. Alcune versioni lasciano arrivare il sonno in quella sensazione; altre mantengono un'attenzione tranquilla. Puoi fermarti prima che la scena sembri convincente. Non tenerti sveglio per rendere perfetta una scena immaginata. [manifest-P15]","4. Tieni separate le affermazioni metafisiche dalle istruzioni. Una rassegna sulla veglia descrive circuiti del sonno e della veglia che interagiscono; non dimostra che il dormiveglia realizzi desideri. L'insegnamento di Goddard secondo cui non occorre agire non è una conclusione della ricerca sulla simulazione mentale. [manifest-P15, manifest-T19, manifest-T04]"]},{heading:"Prova un passo e proteggi il sonno",paragraphs:["Scegli un obiettivo preciso e indica l'ostacolo prima di sistemarti. Per un corso di formazione, potresti verificare se i costi sono alla tua portata. Prova brevemente a fare la domanda reale, compreso ciò che farai se la risposta esclude quel corso. È l'adattamento pratico di ODA; non deve riprodurre la sensazione o la scena prescritta da Goddard. [manifest-P15, manifest-T04]","La sintesi di Cole e colleghi ha rilevato un beneficio medio sul comportamento dalla simulazione mentale in studi diversi, condotti soprattutto con studenti. Non ha stabilito una graduatoria affidabile tra i tipi di simulazione né un vantaggio particolare prima del sonno. Neanche la rassegna sulla veglia dimostra che la sonnolenza aggiri il pensiero o produca risultati esterni. Le prove generali sulle immagini mentali non convalidano ogni affermazione sul SATS. [manifest-T04, manifest-T19]","Scegli un momento di giorno per la domanda reale e fai una richiesta utile oggi, quando è appropriato. Domani annota domanda e risposta separatamente dalle immagini. Se la scena ti tiene più sveglio, fermati: prova di giorno o evita le immagini. L'azione successiva può restare prevista anche se lasci la scena incompleta. Questa intera sequenza non è stata testata come intervento SATS. [manifest-P15, manifest-T04, manifest-T19]"]}],sources:["manifest-P15","manifest-T04","manifest-T19"]}],n=l.sort((i,e)=>i.number-e.number).map(s),c=[...t,{id:"M01",title:"Wang, Wang & Gai · 2021 · Contrasto mentale e intenzioni di attuazione",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 effetti indipendenti da 21 articoli, 15.907 partecipanti: modesto beneficio medio nel raggiungere gli obiettivi, g = 0,336 [0,229; 0,443]. La correzione per la distorsione da pubblicazione stimava 0,242 [0,143; 0,342].",limitation:"Risultati molto variabili e indizi di distorsione da pubblicazione. Questo corso e i suoi brevi esercizi non sono stati sperimentati; nessun risultato è garantito."},{id:"M02",title:"Gollwitzer & Sheeran · 2006 · Intenzioni di attuazione e raggiungimento degli obiettivi",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 test indipendenti, 8.461 partecipanti: i piani specifici «se… allora…» favorivano mediamente il raggiungimento degli obiettivi, d = 0,65 [0,60; 0,70].",limitation:"Ricerche meno recenti ed eterogenee, non tutte preregistrate. Un piano non elimina lo sforzo, la necessità di ricordare, i vincoli pratici o l’incertezza."},{id:"M03",title:"Harkin et al. · 2016 · Monitorare i progressi verso un obiettivo",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 esperimenti, 19.951 partecipanti complessivi. L'analisi sul raggiungimento degli obiettivi comprendeva 18.398 persone: d = 0,40 [0,32; 0,48]; una correzione di sensibilità per studi piccoli stimava 0,19 [0,10; 0,28].",limitation:"Obiettivi e interventi diversi. Le associazioni tra caratteristiche degli studi ed entità degli effetti non impongono di condividere pubblicamente i progressi. Questo diario, le scadenze di revisione e il corso ODA non sono stati validati."},{id:"M04",title:"Cole et al. · 2021 · Simulazione mentale e cambiamento del comportamento",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 studi, 123 effetti, 5.685 partecipanti: effetto complessivo della simulazione mentale g = 0,49 [0,37; 0,62]. Il confronto globale tra sottotipi non era statisticamente significativo.",limitation:"Campioni soprattutto studenteschi e simulazioni diverse. Immaginare solo i passaggi dava cinque effetti con una stima inconcludente. Nessuna graduatoria affidabile tra sottotipi, né validazione di questo breve esercizio."},{id:"M07",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Credere nella manifestazione",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Tre campioni di sondaggi online statunitensi, 1.023 partecipanti: credere nella manifestazione era correlato ad alcuni rischi finanziari e fallimenti dichiarati, ma non al reddito o all'istruzione dichiarati.",limitation:"Le associazioni non dimostrano un nesso causale, né verificano oggettivamente ogni tecnica di manifestazione. I risultati finanziari riferiti dalle persone non prevedono il futuro del singolo."},{id:"M10",title:"Gollwitzer & Brandstätter · 1997 · Pianificare un'occasione precisa",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"Lo studio 2 assegnò una relazione a 86 studenti. Tra i 36 autori identificabili che la restituirono, 12/17 con un piano e 6/19 nel gruppo di controllo scrissero entro due giorni.",limitation:"Il confronto 71% contro 32% riguarda chi restituì la relazione, non tutti i reclutati. Pianificare non aumentò le consegne complessive. Compito studentesco circoscritto; nessuna validazione del corso ODA."},{id:"M11",title:"Oettingen et al. · 2015 · Pianificare e organizzare il calendario",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Lo studio 1 analizzò 84 universitari. Il confronto previsto favoriva il contrasto mentale con piani «se… allora…» per le ore programmate, p = 0,03; test globale p = 0,057.",limitation:"Si misuravano ore programmate, non lavoro svolto o produttività. Escluse le risposte incomplete; non sperimentati l'adattamento breve del corso e la classificazione dei vincoli esterni."},{id:"M14",title:"NIMH · Aiuto per i problemi di salute mentale",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Le indicazioni ufficiali spiegano come accedere a cure qualificate e aiuto nelle crisi, in presenza di disagio, difficoltà nel funzionamento quotidiano o pericolo immediato.",limitation:"Indicazioni, non uno studio di efficacia. ODA non diagnostica né tratta disturbi mentali; fuori dagli Stati Uniti rivolgiti ai servizi sanitari e di emergenza locali."},{id:"manifest-positive-fantasies",title:"Kappes & Oettingen · 2011 · Fantasie positive idealizzate",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Quattro esperimenti, soprattutto con studenti, rilevarono minore energia immediata dopo alcune fantasie positive idealizzate. Lo studio 3 confrontava fantasie positive con fantasie neutre o libere, non con fantasie che mettevano in dubbio l’esito.",limitation:"Esperimenti piccoli e brevi. Non ogni forma di ottimismo o immaginazione è dannosa; non sono stati misurati un ciclo ricorrente di fantasie o un segnale cerebrale di obiettivo raggiunto."},{id:"manifest-belief-study",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Credere nella manifestazione",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Tre sondaggi online statunitensi, 1.023 partecipanti complessivi, associavano la credenza nella manifestazione alla fiducia e ad alcuni rischi finanziari dichiarati, compreso il fallimento. Nessuna associazione con reddito o istruzione dichiarati.",limitation:"Le associazioni non dimostrano causalità né verificano oggettivamente ogni tecnica. I risultati riferiti dalle persone non prevedono il futuro del singolo."},{id:"manifest-murphy",title:"Joseph Murphy · Il potere del subconscio · Provenienza editoriale",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"L'editore identifica il libro divulgativo di Murphy e i suoi insegnamenti su immaginazione e convinzioni.",limitation:"Sinossi editoriale, non studio controllato. Non verificati i passaggi precisi sul rituale serale. Nessuna prova qui di attrazione della ricchezza, guarigione o apprendimento particolarmente efficace prima di dormire."}],a=[{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"it",title:"Il sogno è ancora fermo? Fai qualcosa di utile",goal:"Completa una parte di lavoro che puoi usare per un obiettivo scelto da te.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Un'altra settimana a desiderare una vita diversa? Dai a quel desiderio un primo risultato concreto.",reason:{id:"manifest-1-reason",label:"Di chi è l’obiettivo? A cosa vuoi dedicare tempo?",kind:"text",maxLength:160,optional:!0,suggestions:["Obiettivo mio; stasera i social aspettano","Priorità familiare; rifinire può aspettare","Di altri; valuto se dedicargli tempo","Non so di chi sia l'obiettivo"]},why:{id:"manifest-1-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Un lavoro migliore è un risultato. Riscrivere una riga del curriculum è un'azione. Sono comunque gli altri a decidere se chiamarti. Scegli un lavoro che valga la pena fare. La loro risposta non misura il tuo impegno.","In un esperimento con studenti, scegliere ora e luogo di inizio migliorò la puntualità tra chi restituì una relazione. Non aumentò le consegne complessive. Un piano può aiutarti a partire; non garantisce risultati. Oggi scrivi una riga utilizzabile, una risposta o una richiesta. Mantieni questo obiettivo per tutto il corso e torna a raccontare cosa è successo davvero."],example:{title:"Daniele comincia",text:"Dopo cena, al tavolo della cucina, Daniele dedica dieci minuti al suo obiettivo: lavorare nella logistica. Riscrive una riga del curriculum sull’organizzazione di otto turni in magazzino. La frase è ancora poco scorrevole. La salva e annota la modifica. Nessun datore di lavoro l'ha ancora vista. Domani potrà migliorare una bozza vera."}},move:{invitation:"Scegli un'azione utile per te; gli esempi riguardano il curriculum di Daniele.",instructions:["Prima di salvare, indica il documento, la domanda o l'oggetto da modificare.","Fai il minimo scelto; annotalo separatamente dalle risposte degli altri."],prompts:[],suggestions:{action:["Riscrivi una riga sui turni nel curriculum","Chiedi quale dettaglio manca nel curriculum","Prepara un esempio di copertura dei turni"],minimum:["Salva una frase del curriculum sui turni","Invia la domanda sul dettaglio del curriculum","Salva un esempio di copertura dei turni"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Fra due giorni",daysFromToday:2}],cue:["Dopo aver sparecchiato","Alla fine del pranzo","Dopo aver bevuto qualcosa al mattino"],place:["Al tavolo della mia cucina","Alla postazione in biblioteca","Nel documento del curriculum"],minutes:[10,2,5],fallback:["Descrivi un cambio turno con parole semplici","Scegli e indica un altro momento disponibile","Chiedi in biblioteca come usare un computer"],observation:["La frase del curriculum che ho salvato","Se ho inviato la domanda sul curriculum","Cosa ha impedito il minimo"]},suggested:{action:"Riscrivi una riga sui turni nel curriculum",minimum:"Salva una frase del curriculum sui turni",minutes:10,cueHint:"Dopo aver sparecchiato",placeHint:"Al tavolo della mia cucina",obstacleHint:"Ho meno tempo del previsto",fallbackHint:"Descrivi un cambio turno con parole semplici",observationHint:"La frase del curriculum che ho salvato"},accessibleAlternative:"Scrivi, detta o usa i tuoi strumenti abituali; se serve, chiedi un aiuto pratico.",stopRule:"Sospendi passi rischiosi o che non puoi permetterti; scegli un aiuto pratico."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto o realizzato davvero?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Daniele ha trovato un'offerta adatta e ha dieci minuti prima di cena. Il curriculum non descrive l'organizzazione dei turni richiesta dal ruolo.",question:"Quale primo tentativo è più utile?",options:[{id:"manifest-1-research-more",text:"Confrontare altre offerte per capire se questo ruolo corrisponde davvero alla vita che desidera.",feedback:"Confrontare i ruoli può chiarire un obiettivo. Questa offerta è già adatta; manca una descrizione utilizzabile dell'esperienza di Daniele. Migliora quella riga nel tempo disponibile."},{id:"manifest-1-improve-line",text:"Riscrivere una riga per questa offerta, salvare la bozza e annotare cosa va ancora migliorato.",feedback:"Daniele ottiene qualcosa di utilizzabile in dieci minuti. La bozza può aver bisogno di un parere e il datore di lavoro può non rispondere. Nessuna delle due cose cancella il lavoro fatto."},{id:"manifest-1-clarify-future",text:"Descrivere nei dettagli la giornata lavorativa ideale prima di decidere cosa inserire nel curriculum.",feedback:"Una giornata ideale può guidare scelte future. Daniele ha già scelto un ruolo adatto. Descriverlo ancora rimanda il problema concreto. Scrivi la riga del curriculum, poi valuta cosa manca."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"Dai al desiderio un'azione utile. Annota l'azione separatamente dalla risposta che speri di ricevere.",followUp:{questionId:"manifest-1-return",question:"Quale lavoro utilizzabile resta dopo il tentativo che avevi pianificato?",observationPrompt:"Cosa è successo al momento scelto?",adjustmentPrompt:"Quale modifica provare alla prossima occasione?"}},goDeeper:{sections:[{heading:"A cosa può servire un piano per cominciare",paragraphs:["Nello studio 2 del 1997, Gollwitzer e Brandstätter assegnarono a 86 studenti di Monaco una relazione sul Natale. Chi pianificava sceglieva ora e luogo precisi, immaginava quell'occasione, si impegnava a cominciare e annotava le scelte. Tra i 36 autori identificabili che restituirono la relazione, 12 su 17 con un piano e sei su 19 nei controlli scrissero entro i due giorni richiesti. Le percentuali riguardano chi restituì il testo, non tutti i reclutati. Pianificare non aumentò le consegne complessive. [M10]","La lezione riprende la scelta di un'occasione concreta, poi ti chiede di usarla per un lavoro utile. Questo adattamento generale non è stato sperimentato nello studio natalizio. Una data, da sola, non ti dice come trovare il tempo. Scegli un evento riconoscibile e un luogo accessibile. Se mancano risorse, richiederle può essere il passo da fare. Annota quella richiesta per ciò che è: aver chiesto aiuto, anche se l'aiuto non è ancora arrivato."]},{heading:"Un desiderio non decide per gli altri",paragraphs:["La revisione del 2021 di Wang e colleghi riuniva 24 effetti indipendenti da 21 articoli, con 15.907 partecipanti. Accostare un risultato desiderato a un ostacolo e a una risposta «se… allora…» mostrava un modesto beneficio medio nel raggiungere gli obiettivi: g = 0,336, intervallo di confidenza al 95% da 0,229 a 0,443. I risultati variavano molto e una correzione per la distorsione da pubblicazione riduceva la stima. Sostiene una pianificazione con limiti chiari, non una promessa sul corso. [M01]","Dixon e colleghi studiarono la credenza nella manifestazione in tre sondaggi online statunitensi, per 1.023 partecipanti complessivi. La credenza era correlata ad alcuni rischi finanziari e fallimenti dichiarati, ma non a reddito o istruzione dichiarati. Queste associazioni non dimostrano che la credenza causasse fallimenti, né verificano oggettivamente ogni esercizio di manifestazione. [M07] Usa il desiderio per scegliere cosa fare e valutare i vincoli. Non dedurre che i pensieri abbiano attirato occasioni, causato difficoltà o reso meritato un risultato. Contano anche denaro, responsabilità di cura, accesso alle risorse e decisioni degli altri."]}],sourceIds:["M10","M01","M07"]}},{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"it",title:"Continui a immaginare? Arriva al primo passo vero",goal:"Prova mentalmente un punto difficile, poi realizza la prossima parte utile del lavoro già scelto.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"Pagina bianca? Il risultato è facile da immaginare. Prova mentalmente il primo gesto, poi fallo.",reason:{id:"manifest-2-reason",label:"Un'altra prova mentale ti aiuta o sostituisce il tentativo vero?",kind:"text",maxLength:160,optional:!0,suggestions:["Fa emergere un'istruzione mancante","Rimanda una frase già pronta","Non ho ancora annotato prove mentali"]},why:{id:"manifest-2-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Riprendi il compito scelto e le tue annotazioni. Provare mentalmente significa eseguire nella mente un gesto preciso, come pronunciare la prima frase. Elencare i passaggi è un'altra forma di preparazione. Nessuna delle due è il tentativo vero.","Una revisione ha trovato benefici medi sul comportamento dalla simulazione mentale, senza stabilire quale tipo sia migliore. Non dimostra che questa breve prova funzioni. Usala per individuare dove ti blocchi e cosa fare lì. Se non arrivano immagini, descrivi il gesto a parole. Poi scrivi la prossima riga utilizzabile dello stesso lavoro."],example:{title:"Daniele davanti alla riga vuota",text:"Daniele riapre il curriculum dopo cena. Per trenta secondi prova mentalmente a descrivere un cambio turni difficile. Teme di bloccarsi, così prova l'inizio: «Ho modificato otto turni quando…» Poi scrive una frase utilizzabile. Elimina due parole e lascia una domanda per chiedere un parere. La prova mentale non aveva previsto quanti dettagli servissero."},rehearsal:{label:"Preparazione facoltativa",steps:["Descrivi il prossimo gesto e un punto in cui potresti bloccarti.","Prova mentalmente la prima risposta una volta. È preparazione."]}},move:{invitation:"Mantieni il compito scelto; gli esempi sul curriculum si possono modificare.",instructions:["Mantieni azione, minimo, momento e luogo previsti nel piano; lavora sul punto difficile.","Se non hai un piano, indica azione e momento disponibile prima di salvare.","Prova mentalmente una volta, poi agisci; la sola prova è preparazione."],prompts:[],suggestions:{action:["Prova mentalmente, poi scrivi una frase sui turni","Prova mentalmente, poi chiedi un dettaglio del curriculum","Correggi una data seguendo passaggi scritti"],minimum:["Salva una frase dopo la prova mentale","Invia la domanda sul dettaglio del curriculum","Salva una data corretta nel curriculum"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Fra due giorni",daysFromToday:2}],cue:["Dopo aver sparecchiato","Alla fine del pranzo","Quando apro il documento del curriculum"],place:["Al tavolo della mia cucina","Alla postazione in biblioteca","Nel documento del curriculum"],minutes:[5,2,10],fallback:["Basta prove mentali: descrivi un cambio turno vero","Salta le immagini; usa il primo passo scritto","Chiedi a chi legge quale dettaglio manca"],observation:["Cosa la prova mentale non aveva previsto","La frase del curriculum che ho scritto","Se ho fatto solo una prova mentale"]},suggested:{action:"Prova mentalmente, poi scrivi una frase sui turni",minimum:"Salva una frase dopo la prova mentale",minutes:5,cueHint:"Dopo aver sparecchiato",placeHint:"Al tavolo della mia cucina",obstacleHint:"Continuo a rifinire la prova mentale senza cominciare",fallbackHint:"Basta prove mentali: descrivi un cambio turno vero",observationHint:"Cosa la prova mentale non aveva previsto"},accessibleAlternative:"Scrivi, detta o usa i tuoi strumenti abituali; se serve, chiedi un aiuto pratico.",stopRule:"Se pianificare a letto ti tiene sveglio, fermati e scegli un momento diurno."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto o realizzato davvero?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Daniele sa descrivere la prima frase del curriculum e il documento è pronto. Vorrebbe provare mentalmente tutta la candidatura un'altra volta.",question:"Quale passo serve a questo tentativo?",options:[{id:"manifest-2-full-rehearsal",text:"Provare mentalmente tutta la candidatura ancora una volta, per scegliere l'inizio migliore prima di scrivere.",feedback:"Una prova completa può preparare il lavoro successivo. Daniele ha già un inizio utilizzabile e il documento pronto. Riprovare tutto rimanda il tentativo disponibile. Scrivi la frase e rileggila."},{id:"manifest-2-new-goal-scene",text:"Immaginare il primo giorno nel nuovo ruolo per ritrovare la motivazione, poi tornare alla candidatura più tardi.",feedback:"Immaginare il ruolo può chiarire perché conta. Non mette alla prova l'inizio preparato da Daniele. Usa subito la frase nel documento, poi osserva cosa è stato più difficile del previsto."},{id:"manifest-2-perform-opening",text:"Provare mentalmente la prima frase una volta, scriverla nella bozza e confrontare la difficoltà reale con quella prevista.",feedback:"Qui la preparazione serve a fare davvero qualcosa. Daniele avrà una frase da rivedere. La qualità e il disagio restano aspetti da valutare, senza diventare condizioni per riconoscere che il tentativo c'è stato."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"Dopo la preparazione, agisci davvero. Annota separatamente le due cose.",followUp:{questionId:"manifest-2-return",question:"Che differenza c'è stata tra provare il gesto nella mente e farlo davvero?",observationPrompt:"Cosa è successo al momento scelto?",adjustmentPrompt:"Quale modifica provare alla prossima occasione?"}},goDeeper:{sections:[{heading:"Cosa la ricerca sulla simulazione confronta, e cosa non classifica",paragraphs:["La revisione del 2021 di Cole e colleghi riuniva 94 studi, 123 effetti e 5.685 partecipanti. La simulazione mentale mostrava un effetto complessivo sul comportamento di g = 0,49, intervallo di confidenza al 95% da 0,37 a 0,62. I campioni erano soprattutto studenteschi. Le simulazioni differivano per contenuti, durata e risultati misurati: la media non prevede l'esito del tuo breve esercizio. [M04]","La revisione distingueva il ragionare sui passaggi dall'eseguire mentalmente un compito. La stima sui soli passaggi usava cinque effetti; l'intervallo di confidenza includeva l'assenza di effetto. Il confronto globale tra sottotipi non era statisticamente significativo. Medie più alte nei sottogruppi non indicano quindi un vincitore affidabile. Un grafico non ti chiede di visualizzare con più intensità. Qui provi mentalmente per individuare un dettaglio pratico, poi affronti il compito. Descriverlo per iscritto è una scelta di accessibilità, non una dichiarazione di equivalenza alle immagini dimostrata dalla ricerca."]},{heading:"Preparati a un'occasione, poi usala",paragraphs:["Nell'esperimento originale sulla relazione, i partecipanti immaginavano un'ora e un luogo precisi per cominciare. Il confronto sulla puntualità riguardava autori identificabili che avevano restituito il testo e un compito studentesco circoscritto. Non dimostra un copione universale per immaginare, né un beneficio delle prove a letto. [M10] Qui la preparazione ha senso quando ti aiuta a realizzare la prossima parte del lavoro che serve al tuo obiettivo.","Potresti accorgerti di una password mancante, un'istruzione poco chiara o una frase che non sai ancora spiegare. Recuperare la password è preparazione; inviare le informazioni richieste è lavoro sul compito. Distinguili nelle annotazioni. Se pianificare a letto ti tiene sveglio, fermati e scegli un momento diurno. È un adattamento pratico del corso. La breve prova mentale è facoltativa: non è un rituale validato né una condizione per partire. Non servono immagini vivide o sensazioni particolari."]}],sourceIds:["M04","M10"]}},{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"it",title:"L'ostacolo c'è. Cambia le condizioni",goal:"Usa l'ultimo tentativo per scegliere e provare una risposta fattibile all'ostacolo.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Figli da seguire, strumenti mancanti o sfinimento? Crederci di più non riorganizza la giornata.",reason:{id:"manifest-3-reason",label:"Cosa richiede aiuto e cosa puoi cambiare ora?",kind:"text",maxLength:160,optional:!0,suggestions:["Il computer condiviso richiede un accordo","Posso ridurre la modifica al curriculum","Oggi le responsabilità di cura non lasciano spazio","Non ho ancora incontrato un ostacolo"]},why:{id:"manifest-3-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Riprendi lo stesso obiettivo e le annotazioni dei tentativi. Non hai ancora provato? Indica un ostacolo probabile. «Dopo cena il computer condiviso non è disponibile» suggerisce cosa cambiare. «Non ho disciplina» non identifica la condizione.","Gli studi che univano risultato desiderato, ostacolo reale e risposta «se… allora…» hanno trovato modesti benefici medi. Non hanno dimostrato che funzioni grazie al disagio. Denaro, responsabilità di cura, tempo e accesso sono condizioni concrete, non difetti nelle tue convinzioni. Prova una modifica: meno lavoro, un momento disponibile o una richiesta precisa di aiuto. Una richiesta dimostra che hai chiesto, non che hai ricevuto aiuto."],example:{title:"Daniele cambia momento",text:"Daniele voleva modificare ancora il curriculum dopo cena, ma sua figlia usava il computer condiviso per i compiti. Annota la sovrapposizione. Chiede di poterlo usare per dieci minuti prima di cena il giorno dopo. Si accordano. In quel momento migliora una riga, poi si ferma. La candidatura ha ancora bisogno di lavoro."}},move:{invitation:"Manca l’accesso? Scegli «Adatta questo passo», poi «Supporto». Indica il contatto; esempio: la richiesta di Daniele.",instructions:["Se l'accesso è già concordato, mantieni azione, minimo, momento e luogo scelti.","Se manca, nella richiesta di aiuto indica persona, risorsa e momento necessario.","Annota la richiesta separatamente dall'aiuto ricevuto o dal lavoro completato."],prompts:[],suggestions:{action:["Chiedi a tua figlia: computer prima di cena","Chiedi in biblioteca quando c'è un computer libero"],minimum:["Chiedi a tua figlia dieci minuti al computer","Invia la domanda sull'accesso ai computer in biblioteca"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Fra due giorni",daysFromToday:2}],cue:["Quando organizziamo i compiti a casa","Dopo il pranzo di oggi","Dopo aver sparecchiato"],place:["Al tavolo della mia cucina","Nel modulo di contatto della biblioteca","Alla postazione in biblioteca"],minutes:[5,2,10],fallback:["Chiedi in biblioteca come usare un computer","Chiedi in famiglia un momento al computer","Sospendi finché concordate un momento fattibile"],observation:["La richiesta di accesso e l'eventuale risposta","Se abbiamo concordato l'uso del computer","Se ho fatto la modifica al curriculum"]},suggested:{action:"Chiedi a tua figlia: computer prima di cena",minimum:"Chiedi a tua figlia dieci minuti al computer",minutes:5,cueHint:"Quando organizziamo i compiti a casa",placeHint:"Al tavolo della mia cucina",obstacleHint:"Mia figlia non può lasciarmi il computer",fallbackHint:"Chiedi in biblioteca come usare un computer",observationHint:"La richiesta di accesso e l'eventuale risposta",kind:"support"},accessibleAlternative:"Scrivi, parla o fatti aiutare. Dopo aver concordato l'accesso, scegli «Adatta questo passo» per il lavoro sul compito.",stopRule:"Se l'esercizio ti sopraffà o il contesto non è sicuro, fermati e cerca un supporto adeguato."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto o realizzato davvero?"},judgment:{primary:{id:"manifest-3-decision",scenario:"La modifica serale di Daniele si sovrappone ai compiti sul computer condiviso. Dieci minuti prima di cena sono disponibili, se si accordano.",question:"Quale risposta affronta questo ostacolo?",options:[{id:"manifest-3-arrange-opening",text:"Concordare i dieci minuti disponibili e usarli per migliorare una riga della stessa bozza.",feedback:"Cambia la condizione che impediva il lavoro e mantiene un minimo utile. Serve ancora l'accordo. Se il momento non è confermato, annota separatamente la richiesta."},{id:"manifest-3-keep-evening",text:"Mantenere l'appuntamento serale e aggiungere una prova mentale più lunga, per sentirsi pronto quando il computer sarà libero.",feedback:"Provare mentalmente può preparare le parole, ma non risolve la sovrapposizione. Daniele ha un possibile momento alternativo. Concorda quello prima di aggiungere un'altra routine di preparazione."},{id:"manifest-3-wait-week",text:"Aspettare che la prossima settimana diminuiscano i compiti, poi ripartire con la sessione più lunga inizialmente prevista.",feedback:"Aspettare può essere giusto quando non c'è un momento fattibile. Qui si può forse concordarne uno più breve adesso. Prova questa possibilità, senza rimandare automaticamente tutto il lavoro."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Indica la condizione che ti blocca. Cambia il compito o chiedi l'aiuto che serve davvero.",followUp:{questionId:"manifest-3-return",question:"Hai inviato la richiesta di accesso o lavorato sul compito? Quale accordo manca ancora?",observationPrompt:"Cosa è successo al momento scelto?",adjustmentPrompt:"Quale modifica provare alla prossima occasione?"}},goDeeper:{sections:[{heading:"L'ostacolo dà informazioni, non è un ingrediente",paragraphs:["La revisione del 2021 sul contrasto mentale con pianificazione ha trovato un modesto miglioramento medio nel raggiungere gli obiettivi, su 24 effetti indipendenti. La forte variabilità e gli indizi di distorsione da pubblicazione limitano la certezza. Non ha isolato il disagio come ingrediente attivo. Riconoscere una difficoltà può essere spiacevole; aumentare apposta il disagio non è il compito. [M01]","La procedura del 2015 di Oettingen e colleghi esaminata nel dossier chiedeva agli studenti di approfondire un risultato desiderato e l'ostacolo principale, scegliere una risposta, collegare ostacolo e azione, aggiungere ora e luogo abituali. Nello studio 1, il confronto previsto favoriva il metodo per le ore programmate in calendario. Si misurava la programmazione, non il lavoro svolto; il test globale tra condizioni era inconcludente. [M11] ODA aggiunge un controllo pratico di fattibilità e un tentativo vero. Né l'esercizio più breve né la distinzione tra condizioni esterne e risposte personali sono stati validati separatamente da quell'esperimento."]},{heading:"Quando la risposta giusta è chiedere aiuto",paragraphs:["Distingui il risultato desiderato dalle condizioni necessarie per cercarlo. Se manca uno strumento, serve accesso; se c'è un pericolo, protezione; se devi occuparti di qualcuno, può servire un altro momento. È una scelta del corso ispirata dalla ricerca sui piani, non una classificazione che mette ogni ostacolo in una casella. Una richiesta è concreta quando indica l'aiuto e l'occasione necessari. [M01, M11]","Se una persona non ha risposto, annota la richiesta e l'assenza di risposta. Non segnare aiuto ricevuto o compito completato. Puoi scegliere un altro passo fattibile, rivedere l'obiettivo o fermarti. Se il disagio persiste o limita molto la vita quotidiana, cerca un supporto qualificato invece di intensificare l'esercizio. Le indicazioni NIMH spiegano come accedere a cure e aiuto nelle crisi; non provano che ODA tratti un disturbo. [M14] La prossima annotazione deve descrivere l'azione scelta, compresa protezione o aiuto, senza trasformare l'ostacolo iniziale in un difetto delle tue convinzioni."]}],sourceIds:["M01","M11","M14"]}},{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"it",title:"Non aspettare l'umore giusto",goal:"Scegli un momento riconoscibile e una piccola risposta all’ostacolo che hai osservato.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"«Quando mi sentirò pronto» continua a slittare. Scegli un momento che puoi riconoscere davvero.",reason:{id:"manifest-4-reason",label:"L'ultima volta che era il momento di partire, cosa ti è costato rimandare?",kind:"text",maxLength:160,optional:!0,suggestions:["Ho confrontato esempi senza scrivere","Ho aspettato; la bozza è rimasta intatta","Dovevo occuparmi di qualcuno; mancava un momento sicuro","Nessun momento precedente; potrei bloccarmi sulle parole"],help:"Non hai ancora provato? Indica un'esitazione possibile."},why:{id:"manifest-4-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Il momento per cominciare e la risposta all'ostacolo servono a cose diverse. «Dopo aver sparecchiato, scrivi una riga del curriculum» crea un'occasione. «Se ti blocchi, descrivi un cambio turno» ti aiuta dentro quell'occasione.","Ricerche su obiettivi diversi hanno trovato che i piani specifici «se… allora…» aiutano mediamente a proseguire. Non eliminano lo sforzo, la necessità di ricordare o i vincoli pratici. Mantieni il compito; rispondi a un ostacolo osservato, se c'è. Scegli un momento riconoscibile e una risposta che puoi dare lì. Se quel momento non arriva, annota che è mancata l'occasione e scegline un'altra."],example:{title:"Daniele riconosce il momento",text:"Daniele mette un biglietto accanto al computer condiviso: «Dopo aver sparecchiato, migliora una riga. Se ti blocchi, descrivi un cambio turno». Giovedì arriva quel momento e nota il biglietto. Scrive una riga utile, ma non finisce la sezione prima che riprendano gli impegni familiari. Annota entrambe le cose."}},move:{invitation:"Mantieni compito e momento reali. Gli esempi riguardano il curriculum di Daniele.",instructions:["Mantieni azione, minimo, momento e luogo previsti nel piano, salvo una modifica necessaria.","Prima di salvare, indica una risposta più piccola al punto che ti blocca."],prompts:[],suggestions:{action:["Dopo cena, scrivi una frase sui turni","Dopo pranzo, invia la domanda sul curriculum","Dopo il tè, correggi una data del curriculum"],minimum:["Salva una frase del curriculum sui turni","Invia la domanda sul dettaglio del curriculum","Salva una data corretta nel curriculum"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Fra due giorni",daysFromToday:2}],cue:["Dopo aver sparecchiato","Alla fine del pranzo","Quando poso la tazza del tè"],place:["Al tavolo della mia cucina","Nel documento del curriculum","Alla postazione in biblioteca"],minutes:[5,2,10],fallback:["Descrivi un cambio turno in una frase","Scegli e indica un altro momento disponibile","Chiedi in biblioteca come usare un computer"],observation:["Se il momento è arrivato e l'ho notato","Se ho descritto il cambio turno","La modifica al curriculum che ho salvato"]},suggested:{action:"Dopo cena, scrivi una frase sui turni",minimum:"Salva una frase del curriculum sui turni",minutes:5,cueHint:"Dopo aver sparecchiato",placeHint:"Al tavolo della mia cucina",obstacleHint:"Arriva il momento, ma mi blocco sulle parole",fallbackHint:"Descrivi un cambio turno in una frase",observationHint:"Se il momento è arrivato e l'ho notato"},accessibleAlternative:"Scrivi, detta o usa i tuoi strumenti abituali; se serve, chiedi un aiuto pratico.",stopRule:"Rispetta impegni di cura e sicurezza; scegli un altro momento se questo non va più bene."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto o realizzato davvero?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Daniele ha cinque minuti dopo aver sparecchiato. Ha la bozza e un esempio corretto di cambio turno, ma si blocca sulle parole.",question:"Quale piano aiuta sia a partire sia quando si blocca?",options:[{id:"manifest-4-mood-cue",text:"Quando si sente più lucido dopo cena, dedicare cinque minuti alla sezione del curriculum con gli esempi migliori.",feedback:"Sentirsi più lucido sarebbe piacevole, ma rende variabile il momento di partenza. Usa il gesto osservabile di sparecchiare e una risposta abbastanza piccola per i cinque minuti disponibili."},{id:"manifest-4-full-section",text:"Dopo aver sparecchiato, confrontare tre esempi di organizzazione dei turni prima di scegliere il migliore per la riga del curriculum.",feedback:"Confrontare può aiutare a scegliere. Daniele ha già un esempio corretto; cercarne altri consumerebbe i cinque minuti. Descrivi prima quel cambio turno. Rivedi le parole quando esiste una riga vera."},{id:"manifest-4-cue-and-response",text:"Dopo aver sparecchiato, migliorare una riga; se le parole non arrivano, descrivere con semplicità un cambio turno reale.",feedback:"Il piano distingue il momento di partenza dal punto difficile e dice cosa fare in entrambi. Daniele può provarlo con la bozza pronta. Aiuta a fare un passo senza promettere che ricorderà tutto senza fatica o finirà la sezione."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Scegli quando partire e cosa fare se ti blocchi. Poi verifica cosa è successo davvero.",followUp:{questionId:"manifest-4-return",question:"Hai riconosciuto il momento per cominciare? Hai potuto usare la risposta prevista?",observationPrompt:"Cosa è successo al momento scelto?",adjustmentPrompt:"Quale modifica provare alla prossima occasione?"}},goDeeper:{sections:[{heading:"A cosa serve un piano preciso",paragraphs:["Il capitolo del 2006 di Gollwitzer e Sheeran riuniva 94 test indipendenti con 8.461 partecipanti. Pianificare con «se… allora…» mostrava un effetto medio sul raggiungimento degli obiettivi di d = 0,65, intervallo di confidenza al 95% da 0,60 a 0,70. Compiti e procedure variavano; queste ricerche meno recenti non erano tutte preregistrate. Non dimostrano che qualsiasi frase scritta da una persona funzionerà. [M02]","Nell'esperimento sulla pianificazione di un'occasione, gli studenti sceglievano ora e luogo precisi per iniziare una relazione. Il confronto sulla puntualità riguardava chi la restituiva ed era identificabile, non tutti gli assegnatari. [M10] Il messaggio pratico è più limitato di «un piano sostituisce la volontà». Scegli prima una risposta, poi verifica se la situazione c'è stata, l'hai notata e la risposta era adatta. Usa promemoria esterni se ti servono. Un biglietto accanto a uno strumento è un'opzione ODA, non una garanzia sperimentata di accorgersene."]},{heading:"Due funzioni nello stesso esperimento",paragraphs:["L'appuntamento per cominciare dice quando proverai il compito. La risposta all'ostacolo dice cosa farai se compare una difficoltà osservata. La procedura di contrasto mentale esaminata collegava ostacolo e risposta, aggiungendo ora e luogo abituali; non stabiliva che tutti abbiano bisogno di due regole separate. [M11] Il corso distingue queste funzioni per capire più facilmente cosa succede nell'esperimento che hai già avviato.","Metti che l'occasione prevista non arrivi. Non puoi dire che la risposta all'ostacolo abbia fallito. Se arriva ma non la noti, cambia il momento o il promemoria. Se la noti ma la risposta è troppo grande, riduci la prossima parte utile del compito. Sono scelte da provare, non conclusioni dimostrate da un diario privato. Mantieni le vecchie annotazioni legate al minimo originale. Un nuovo piano non rende completo un tentativo passato incompleto. Rivedi l'azione fatta e conserva la possibilità di chiedere aiuto, riposare, fermarti o cambiare obiettivo."]}],sourceIds:["M02","M10","M11"]}},{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"it",title:"Il risultato non arriva? Guarda cosa hai fatto",goal:"Dalle annotazioni dell’esperimento, scegli un prossimo passo fattibile e quando rivederlo la settimana prossima.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Prima di lasciare il sogno, verifica se hai provato la strada o hai solo continuato a pianificarla.",reason:{id:"manifest-5-reason",label:"Cosa ti farebbe continuare, cambiare o fermarti su questa strada?",kind:"text",maxLength:160,optional:!0,suggestions:["Bozza utilizzabile; la invio","Sovrapposizioni ripetute; cambio momento","Parere preciso; riscrivo la frase poco chiara","Nessun tentativo; scelgo una prima prova"]},why:{id:"manifest-5-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Leggi le annotazioni dello stesso obiettivo. Distingui cosa hai pianificato, provato mentalmente, fatto davvero e ricevuto dagli altri. Una bozza salvata dimostra lavoro sulla bozza. Non dimostra che hai inviato la candidatura o che un datore di lavoro sia interessato.","Una revisione di 138 esperimenti ha trovato benefici medi dall'aumento del monitoraggio dei progressi. Non ha validato queste annotazioni né una scadenza ideale per rivederle. Decidi dai fatti: ripeti un passo fattibile, modifica un problema, chiedi un parere o lascia un obiettivo inadatto. Se non hai provato, riconosci quel vuoto e realizza la prima parte utile."],example:{title:"Daniele sceglie il passo della prossima settimana",text:"Daniele rilegge tre modifiche datate e un'occasione mancata al computer. Il curriculum è più chiaro, ma non ha inviato candidature. Sceglie un'offerta adatta, controlla i requisiti e venerdì invia la versione preparata. Annota l'invio e decide di rivederlo la settimana prossima. Non ha ancora ricevuto risposta."}},move:{invitation:"Mantieni ciò che funzionava e indica la prossima azione. Esempio: una candidatura pronta.",instructions:["Se ripeti, mantieni minimo e appuntamento previsti nel piano; cambia solo il problema osservato.","Senza annotazioni, indica una prima azione e il minimo corrispondente prima di salvare.","Richiedere informazioni significa aver chiesto, non aver completato il compito bloccato."],prompts:[],suggestions:{action:["Invia la candidatura pronta per l'offerta scelta","Chiedi al referente di chiarire un requisito","Rivedi una frase del curriculum dopo un parere"],minimum:["Invia una volta la candidatura pronta","Invia la domanda sul requisito della candidatura","Salva la frase rivista del curriculum"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Fra due giorni",daysFromToday:2}],cue:["Alla fine del pranzo","Dopo aver sparecchiato","Quando apro la pagina per candidarmi"],place:["Al tavolo della mia cucina","Alla postazione in biblioteca","Nel modulo di candidatura dell'offerta"],minutes:[10,2,5],fallback:["Chiedi al referente di chiarire il requisito","Chiedi un parere sulla frase poco chiara","Sospendi finché arrivano le informazioni necessarie"],observation:["L'invio e la conferma, se disponibile","La richiesta inviata e la risposta ancora attesa","Cosa resta fuori dal mio controllo"]},suggested:{action:"Invia la candidatura pronta per l'offerta scelta",minimum:"Invia una volta la candidatura pronta",minutes:10,cueHint:"Alla fine del pranzo",placeHint:"Al tavolo della mia cucina",obstacleHint:"Un dettaglio richiesto per candidarmi non è chiaro",fallbackHint:"Chiedi al referente di chiarire il requisito",observationHint:"L'invio e la conferma, se disponibile"},accessibleAlternative:"Scrivi, detta o usa i tuoi strumenti abituali; se serve, chiedi un aiuto pratico.",stopRule:"Non spendere di più né rinunciare a cure necessarie per inseguire un risultato incerto."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto o realizzato davvero?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Daniele ha modificato il curriculum senza candidarsi. Un'offerta adatta scade stasera. La bozza rispetta i requisiti; qualcuno potrà confrontare le versioni domani.",question:"A cosa dovrebbe portare la sua revisione?",options:[{id:"manifest-5-next-application",text:"Inviare la candidatura pronta, annotare l'invio e fissare una revisione successiva, lasciando aperta l'incertezza sulla risposta.",feedback:"Le annotazioni indicano un passo concreto, pronto e sotto il controllo di Daniele. L'azione è inviare. La decisione del datore di lavoro resta sconosciuta finché non arriva una risposta vera."},{id:"manifest-5-double-editing",text:"Chiedere un confronto tra due versioni del curriculum prima di candidarsi, per ridurre il rischio di frasi poco efficaci.",feedback:"Il confronto potrebbe far emergere problemi, ma arriverebbe dopo la scadenza di stasera. Daniele ha controllato i requisiti senza trovare lacune. Invia questa versione adatta; usa i pareri successivi per una modifica concreta."},{id:"manifest-5-change-direction",text:"Sfruttare il momento per inviare più candidature generiche, aumentando le occasioni prima di decidere quale versione del curriculum mantenere.",feedback:"Più candidature possono creare occasioni. Qui una candidatura adatta è già pronta. Inviarla mette alla prova quell'abbinamento. Aumentare il numero potrà essere una scelta futura, senza sostituire questo invio mirato e preparato."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Lascia che le annotazioni cambino il prossimo passo. Impegno, preparazione e risultati esterni raccontano cose diverse.",followUp:{questionId:"manifest-5-return",question:"Cosa è successo con il compito o la richiesta di informazioni? Cosa resta in attesa?",observationPrompt:"Cosa è successo al momento scelto?",adjustmentPrompt:"Quale modifica provare alla prossima occasione?"}},goDeeper:{sections:[{heading:"Monitorare aiuta a decidere",paragraphs:["La revisione del 2016 di Harkin e colleghi comprendeva 138 esperimenti con assegnazione casuale e 19.951 partecipanti complessivi. L'analisi sul raggiungimento degli obiettivi usava 18.398 persone e trovava d = 0,40, intervallo di confidenza al 95% da 0,32 a 0,48. Una correzione di sensibilità per studi piccoli dava una stima inferiore. Interventi, obiettivi e metodi di annotazione differivano. La revisione non ha sperimentato il resoconto ODA né la scheda del giorno dopo. [M03]","Tra gli studi, annotare o condividere pubblicamente i progressi era associato a effetti maggiori. Questi confronti tra studi con caratteristiche diverse non dimostrano che serva esporsi pubblicamente o che un formato dell’app causi benefici. Tieni privati i dettagli personali se è adatto alla tua situazione. Confronta ciò che chiedeva il piano con l'azione che hai riferito. Se manca un'annotazione, l'esito resta sconosciuto. Preparazione completata, richiesta senza risposta e tentativo interrotto devono conservare ciascuno il proprio nome. Così puoi valutare la prossima decisione senza dover raccontare una storia positiva."]},{heading:"Scegli il prossimo passo senza riscrivere questa settimana",paragraphs:["Un breve diario personale può suggerire un andamento, ma non dimostra perché si sia verificato un risultato esterno. Candidature, ordini e risposte altrui possono dipendere da qualità, tempi, risorse o condizioni che il diario non misura. La ricerca sul monitoraggio sostiene l'uso delle informazioni; non stabilisce un numero universale di tentativi prima di cambiare obiettivo. [M03] La revisione deve mantenere visibile questa incertezza.","Scegli una prossima occasione fattibile e quando rivederla nella settimana in arrivo. Mantieni il minimo utile e ciò che ha favorito l'accesso al compito; cambia la parte messa in discussione dalle annotazioni. Se non hai annotato tentativi, riferisci fatti conosciuti o considera il prossimo piccolo gesto il primo esperimento. Non inventare impegno passato. Gli studi sui piani mostrano benefici medi variabili, non risultati garantiti. [M01] Fermarti, chiedere un parere, trovare aiuto pratico o cambiare direzione possono essere decisioni consapevoli della revisione. Conserva le annotazioni precedenti, così resta visibile il motivo della scelta."]}],sourceIds:["M03","M01"]}},...n],u={lang:"it",id:"manifest",title:"Sogno fermo? Comincia con un lavoro concreto",subtitle:"Cinque lezioni di base, poi 15 tecniche diffuse: cosa dice la ricerca e un'azione utile da provare.",description:"Dai un lavoro concreto a un desiderio scelto da te. Continua nella libreria delle tecniche: scopri i rituali, valuta le prove e prova un passo fattibile.",scope:"Qui manifestare significa mettere insieme intenzione, preparazione e azione. Il corso non afferma che i pensieri guidino gli eventi tramite effetti quantistici, che l'universo ti consegni ciò su cui ti concentri o che un desiderio si avveri di sicuro. Non offre consulenza finanziaria, medica o psicologica.",outcome:"Un obiettivo significativo, un piccolo passo utile, annotazioni sincere dei tentativi e un piano fattibile per la prossima settimana.",lessonLibrary:{id:"manifest-technique-library",title:"Libreria delle tecniche",description:"15 rituali conosciuti: come si praticano, cosa sostiene la ricerca e una versione ODA con un’azione da fare e rivedere.",lessonIds:n.map(i=>i.id),sourceIds:t.map(i=>i.id)},photo:{id:"1676782778930-11b311ec5134",alt:"Strada sterrata che sale su una collina erbosa verso montagne lontane"},lessons:[{id:"manifest-1",v2:a[0],photo:{id:"1768055104910-8c8d213835fb",alt:"Una mano scrive una lista di cose da fare su un quaderno"},schemaVersion:2,title:"Il sogno è ancora fermo? Fai qualcosa di utile",minutes:6,goal:"Completa una parte di lavoro che puoi usare per un obiettivo scelto da te.",reading:["Un lavoro migliore è un risultato. Riscrivere una riga del curriculum è un'azione. Sono comunque gli altri a decidere se chiamarti. Scegli un lavoro che valga la pena fare. La loro risposta non misura il tuo impegno.","In un esperimento con studenti, scegliere ora e luogo di inizio migliorò la puntualità tra chi restituì una relazione. Non aumentò le consegne complessive. Un piano può aiutarti a partire; non garantisce risultati. Oggi scrivi una riga utilizzabile, una risposta o una richiesta. Mantieni questo obiettivo per tutto il corso e torna a raccontare cosa è successo davvero."],practice:["Scrivi o pensa, in una frase, a un desiderio che conta per te.","Scegli un'azione sotto il tuo controllo che ti avvicini a quel desiderio.","Descrivi l'azione con un piccolo punto d'arrivo, per esempio «tre righe di una bozza»."],reflection:"Come diventa un'azione di oggi il tuo desiderio?",question:"Quale di queste azioni puoi scegliere direttamente?",options:["Il datore di lavoro mi sceglie sicuramente.","Domani modifico tre righe del curriculum.","Non va storto proprio niente."],correct:1,feedback:"Non puoi garantire le decisioni degli altri. Puoi rendere concreta la tua preparazione.",takeaway:"Dai al desiderio un'azione utile. Annota l'azione separatamente dalla risposta che speri di ricevere.",sources:["M10","M01","M07"],deeper:[{heading:"A cosa può servire un piano per cominciare",paragraphs:["Nello studio 2 del 1997, Gollwitzer e Brandstätter assegnarono a 86 studenti di Monaco una relazione sul Natale. Chi pianificava sceglieva ora e luogo precisi, immaginava quell'occasione, si impegnava a cominciare e annotava le scelte. Tra i 36 autori identificabili che restituirono la relazione, 12 su 17 con un piano e sei su 19 nei controlli scrissero entro i due giorni richiesti. Le percentuali riguardano chi restituì il testo, non tutti i reclutati. Pianificare non aumentò le consegne complessive. [M10]","La lezione riprende la scelta di un'occasione concreta, poi ti chiede di usarla per un lavoro utile. Questo adattamento generale non è stato sperimentato nello studio natalizio. Una data, da sola, non ti dice come trovare il tempo. Scegli un evento riconoscibile e un luogo accessibile. Se mancano risorse, richiederle può essere il passo da fare. Annota quella richiesta per ciò che è: aver chiesto aiuto, anche se l'aiuto non è ancora arrivato."]},{heading:"Un desiderio non decide per gli altri",paragraphs:["La revisione del 2021 di Wang e colleghi riuniva 24 effetti indipendenti da 21 articoli, con 15.907 partecipanti. Accostare un risultato desiderato a un ostacolo e a una risposta «se… allora…» mostrava un modesto beneficio medio nel raggiungere gli obiettivi: g = 0,336, intervallo di confidenza al 95% da 0,229 a 0,443. I risultati variavano molto e una correzione per la distorsione da pubblicazione riduceva la stima. Sostiene una pianificazione con limiti chiari, non una promessa sul corso. [M01]","Dixon e colleghi studiarono la credenza nella manifestazione in tre sondaggi online statunitensi, per 1.023 partecipanti complessivi. La credenza era correlata ad alcuni rischi finanziari e fallimenti dichiarati, ma non a reddito o istruzione dichiarati. Queste associazioni non dimostrano che la credenza causasse fallimenti, né verificano oggettivamente ogni esercizio di manifestazione. [M07] Usa il desiderio per scegliere cosa fare e valutare i vincoli. Non dedurre che i pensieri abbiano attirato occasioni, causato difficoltà o reso meritato un risultato. Contano anche denaro, responsabilità di cura, accesso alle risorse e decisioni degli altri."]}],example:{title:"Daniele comincia",text:"Dopo cena, al tavolo della cucina, Daniele dedica dieci minuti al suo obiettivo: lavorare nella logistica. Riscrive una riga del curriculum sull’organizzazione di otto turni in magazzino. La frase è ancora poco scorrevole. La salva e annota la modifica. Nessun datore di lavoro l'ha ancora vista. Domani potrà migliorare una bozza vera."}},{id:"manifest-2",v2:a[1],photo:{id:"1517363898874-737b62a7db91",alt:"Una persona seduta in silenzio accanto a una finestra nella luce calda"},schemaVersion:2,title:"Continui a immaginare? Arriva al primo passo vero",minutes:6,goal:"Prova mentalmente un punto difficile, poi realizza la prossima parte utile del lavoro già scelto.",reading:["Riprendi il compito scelto e le tue annotazioni. Provare mentalmente significa eseguire nella mente un gesto preciso, come pronunciare la prima frase. Elencare i passaggi è un'altra forma di preparazione. Nessuna delle due è il tentativo vero.","Una revisione ha trovato benefici medi sul comportamento dalla simulazione mentale, senza stabilire quale tipo sia migliore. Non dimostra che questa breve prova funzioni. Usala per individuare dove ti blocchi e cosa fare lì. Se non arrivano immagini, descrivi il gesto a parole. Poi scrivi la prossima riga utilizzabile dello stesso lavoro."],practice:["Indica una differenza che vorresti ottenere nella tua vita con questo obiettivo.","Metti in ordine i primi due passi, con immagini o parole.","Dopo la prova mentale, fai davvero un passo di preparazione."],reflection:"Quale preparazione mancante hai notato durante la prova mentale?",question:"Cosa significa provare mentalmente in questo corso?",options:["Un esercizio che ti prepara a un'azione vera.","Controllare con certezza gli eventi esterni grazie ai pensieri.","Non avere più bisogno di provare."],correct:0,feedback:"Provare mentalmente è preparazione. Gli studi citati non validano questo breve esercizio preciso né dimostrano che controlli i risultati esterni. Usa la preparazione per fare un passo vero.",takeaway:"Dopo la preparazione, agisci davvero. Annota separatamente le due cose.",sources:["M04","M10"],deeper:[{heading:"Cosa la ricerca sulla simulazione confronta, e cosa non classifica",paragraphs:["La revisione del 2021 di Cole e colleghi riuniva 94 studi, 123 effetti e 5.685 partecipanti. La simulazione mentale mostrava un effetto complessivo sul comportamento di g = 0,49, intervallo di confidenza al 95% da 0,37 a 0,62. I campioni erano soprattutto studenteschi. Le simulazioni differivano per contenuti, durata e risultati misurati: la media non prevede l'esito del tuo breve esercizio. [M04]","La revisione distingueva il ragionare sui passaggi dall'eseguire mentalmente un compito. La stima sui soli passaggi usava cinque effetti; l'intervallo di confidenza includeva l'assenza di effetto. Il confronto globale tra sottotipi non era statisticamente significativo. Medie più alte nei sottogruppi non indicano quindi un vincitore affidabile. Un grafico non ti chiede di visualizzare con più intensità. Qui provi mentalmente per individuare un dettaglio pratico, poi affronti il compito. Descriverlo per iscritto è una scelta di accessibilità, non una dichiarazione di equivalenza alle immagini dimostrata dalla ricerca."]},{heading:"Preparati a un'occasione, poi usala",paragraphs:["Nell'esperimento originale sulla relazione, i partecipanti immaginavano un'ora e un luogo precisi per cominciare. Il confronto sulla puntualità riguardava autori identificabili che avevano restituito il testo e un compito studentesco circoscritto. Non dimostra un copione universale per immaginare, né un beneficio delle prove a letto. [M10] Qui la preparazione ha senso quando ti aiuta a realizzare la prossima parte del lavoro che serve al tuo obiettivo.","Potresti accorgerti di una password mancante, un'istruzione poco chiara o una frase che non sai ancora spiegare. Recuperare la password è preparazione; inviare le informazioni richieste è lavoro sul compito. Distinguili nelle annotazioni. Se pianificare a letto ti tiene sveglio, fermati e scegli un momento diurno. È un adattamento pratico del corso. La breve prova mentale è facoltativa: non è un rituale validato né una condizione per partire. Non servono immagini vivide o sensazioni particolari."]}],example:{title:"Daniele davanti alla riga vuota",text:"Daniele riapre il curriculum dopo cena. Per trenta secondi prova mentalmente a descrivere un cambio turni difficile. Teme di bloccarsi, così prova l'inizio: «Ho modificato otto turni quando…» Poi scrive una frase utilizzabile. Elimina due parole e lascia una domanda per chiedere un parere. La prova mentale non aveva previsto quanti dettagli servissero."}},{id:"manifest-3",v2:a[2],photo:{id:"1767134063671-322e6faf9206",alt:"Un albero caduto attraversa un sentiero boscoso coperto di foglie"},schemaVersion:2,title:"L'ostacolo c'è. Cambia le condizioni",minutes:6,goal:"Usa l'ultimo tentativo per scegliere e provare una risposta fattibile all'ostacolo.",reading:["Riprendi lo stesso obiettivo e le annotazioni dei tentativi. Non hai ancora provato? Indica un ostacolo probabile. «Dopo cena il computer condiviso non è disponibile» suggerisce cosa cambiare. «Non ho disciplina» non identifica la condizione.","Gli studi che univano risultato desiderato, ostacolo reale e risposta «se… allora…» hanno trovato modesti benefici medi. Non hanno dimostrato che funzioni grazie al disagio. Denaro, responsabilità di cura, tempo e accesso sono condizioni concrete, non difetti nelle tue convinzioni. Prova una modifica: meno lavoro, un momento disponibile o una richiesta precisa di aiuto. Una richiesta dimostra che hai chiesto, non che hai ricevuto aiuto."],practice:["Indica l'ostacolo più vicino al tuo obiettivo.","Distingui la parte su cui puoi intervenire da quella che richiede aiuto o tempo.","Se ora non è fattibile, riduci l'obiettivo o spostalo a un momento adatto."],reflection:"Guardando l'ostacolo in modo più realistico, cosa è cambiato nel piano?",question:"Quando le condizioni esterne ti ostacolano…",options:["Devo pensare che non ci ho creduto abbastanza.","Devo ignorare le condizioni.","Posso rivedere aiuto, tempi o dimensioni dell'obiettivo."],correct:2,feedback:"Un piano realistico considera le condizioni esterne. I risultati non dipendono solo dai tuoi pensieri.",takeaway:"Indica la condizione che ti blocca. Cambia il compito o chiedi l'aiuto che serve davvero.",sources:["M01","M11","M14"],deeper:[{heading:"L'ostacolo dà informazioni, non è un ingrediente",paragraphs:["La revisione del 2021 sul contrasto mentale con pianificazione ha trovato un modesto miglioramento medio nel raggiungere gli obiettivi, su 24 effetti indipendenti. La forte variabilità e gli indizi di distorsione da pubblicazione limitano la certezza. Non ha isolato il disagio come ingrediente attivo. Riconoscere una difficoltà può essere spiacevole; aumentare apposta il disagio non è il compito. [M01]","La procedura del 2015 di Oettingen e colleghi esaminata nel dossier chiedeva agli studenti di approfondire un risultato desiderato e l'ostacolo principale, scegliere una risposta, collegare ostacolo e azione, aggiungere ora e luogo abituali. Nello studio 1, il confronto previsto favoriva il metodo per le ore programmate in calendario. Si misurava la programmazione, non il lavoro svolto; il test globale tra condizioni era inconcludente. [M11] ODA aggiunge un controllo pratico di fattibilità e un tentativo vero. Né l'esercizio più breve né la distinzione tra condizioni esterne e risposte personali sono stati validati separatamente da quell'esperimento."]},{heading:"Quando la risposta giusta è chiedere aiuto",paragraphs:["Distingui il risultato desiderato dalle condizioni necessarie per cercarlo. Se manca uno strumento, serve accesso; se c'è un pericolo, protezione; se devi occuparti di qualcuno, può servire un altro momento. È una scelta del corso ispirata dalla ricerca sui piani, non una classificazione che mette ogni ostacolo in una casella. Una richiesta è concreta quando indica l'aiuto e l'occasione necessari. [M01, M11]","Se una persona non ha risposto, annota la richiesta e l'assenza di risposta. Non segnare aiuto ricevuto o compito completato. Puoi scegliere un altro passo fattibile, rivedere l'obiettivo o fermarti. Se il disagio persiste o limita molto la vita quotidiana, cerca un supporto qualificato invece di intensificare l'esercizio. Le indicazioni NIMH spiegano come accedere a cure e aiuto nelle crisi; non provano che ODA tratti un disturbo. [M14] La prossima annotazione deve descrivere l'azione scelta, compresa protezione o aiuto, senza trasformare l'ostacolo iniziale in un difetto delle tue convinzioni."]}],example:{title:"Daniele cambia momento",text:"Daniele voleva modificare ancora il curriculum dopo cena, ma sua figlia usava il computer condiviso per i compiti. Annota la sovrapposizione. Chiede di poterlo usare per dieci minuti prima di cena il giorno dopo. Si accordano. In quel momento migliora una riga, poi si ferma. La candidatura ha ancora bisogno di lavoro."}},{id:"manifest-4",v2:a[3],photo:{id:"1591462391971-9ffc57b382b9",alt:"Foglietti adesivi colorati e penne"},schemaVersion:2,title:"Non aspettare l'umore giusto",minutes:6,goal:"Scegli un momento riconoscibile e una piccola risposta all’ostacolo che hai osservato.",reading:["Il momento per cominciare e la risposta all'ostacolo servono a cose diverse. «Dopo aver sparecchiato, scrivi una riga del curriculum» crea un'occasione. «Se ti blocchi, descrivi un cambio turno» ti aiuta dentro quell'occasione.","Ricerche su obiettivi diversi hanno trovato che i piani specifici «se… allora…» aiutano mediamente a proseguire. Non eliminano lo sforzo, la necessità di ricordare o i vincoli pratici. Mantieni il compito; rispondi a un ostacolo osservato, se c'è. Scegli un momento riconoscibile e una risposta che puoi dare lì. Se quel momento non arriva, annota che è mancata l'occasione e scegline un'altra."],practice:["Descrivi un segnale dell'ostacolo usando «Se…».","Nella parte «allora…», scrivi una sola piccola azione.","Controlla che il piano sia adatto al tempo e agli strumenti disponibili, poi provalo mentalmente una volta."],reflection:"Qual è la tua frase «se… allora…»?",question:"Quale piano puoi mettere alla prova davvero?",options:["Si sistemerà tutto da solo.","Se mi blocco quando apro il file, scriverò prima il titolo.","Se mando energia positiva, spariranno tutti gli ostacoli."],correct:1,feedback:"La seconda opzione collega una situazione precisa a un'azione osservabile. È simile alla pianificazione delle azioni studiata nella ricerca.",takeaway:"Scegli quando partire e cosa fare se ti blocchi. Poi verifica cosa è successo davvero.",sources:["M02","M10","M11"],deeper:[{heading:"A cosa serve un piano preciso",paragraphs:["Il capitolo del 2006 di Gollwitzer e Sheeran riuniva 94 test indipendenti con 8.461 partecipanti. Pianificare con «se… allora…» mostrava un effetto medio sul raggiungimento degli obiettivi di d = 0,65, intervallo di confidenza al 95% da 0,60 a 0,70. Compiti e procedure variavano; queste ricerche meno recenti non erano tutte preregistrate. Non dimostrano che qualsiasi frase scritta da una persona funzionerà. [M02]","Nell'esperimento sulla pianificazione di un'occasione, gli studenti sceglievano ora e luogo precisi per iniziare una relazione. Il confronto sulla puntualità riguardava chi la restituiva ed era identificabile, non tutti gli assegnatari. [M10] Il messaggio pratico è più limitato di «un piano sostituisce la volontà». Scegli prima una risposta, poi verifica se la situazione c'è stata, l'hai notata e la risposta era adatta. Usa promemoria esterni se ti servono. Un biglietto accanto a uno strumento è un'opzione ODA, non una garanzia sperimentata di accorgersene."]},{heading:"Due funzioni nello stesso esperimento",paragraphs:["L'appuntamento per cominciare dice quando proverai il compito. La risposta all'ostacolo dice cosa farai se compare una difficoltà osservata. La procedura di contrasto mentale esaminata collegava ostacolo e risposta, aggiungendo ora e luogo abituali; non stabiliva che tutti abbiano bisogno di due regole separate. [M11] Il corso distingue queste funzioni per capire più facilmente cosa succede nell'esperimento che hai già avviato.","Metti che l'occasione prevista non arrivi. Non puoi dire che la risposta all'ostacolo abbia fallito. Se arriva ma non la noti, cambia il momento o il promemoria. Se la noti ma la risposta è troppo grande, riduci la prossima parte utile del compito. Sono scelte da provare, non conclusioni dimostrate da un diario privato. Mantieni le vecchie annotazioni legate al minimo originale. Un nuovo piano non rende completo un tentativo passato incompleto. Rivedi l'azione fatta e conserva la possibilità di chiedere aiuto, riposare, fermarti o cambiare obiettivo."]}],example:{title:"Daniele riconosce il momento",text:"Daniele mette un biglietto accanto al computer condiviso: «Dopo aver sparecchiato, migliora una riga. Se ti blocchi, descrivi un cambio turno». Giovedì arriva quel momento e nota il biglietto. Scrive una riga utile, ma non finisce la sezione prima che riprendano gli impegni familiari. Annota entrambe le cose."}},{id:"manifest-5",v2:a[4],photo:{id:"1762920738995-f393efe82205",alt:"Un cartello di legno indica più direzioni in un bosco"},schemaVersion:2,title:"Il risultato non arriva? Guarda cosa hai fatto",minutes:6,goal:"Dalle annotazioni dell’esperimento, scegli un prossimo passo fattibile e quando rivederlo la settimana prossima.",reading:["Leggi le annotazioni dello stesso obiettivo. Distingui cosa hai pianificato, provato mentalmente, fatto davvero e ricevuto dagli altri. Una bozza salvata dimostra lavoro sulla bozza. Non dimostra che hai inviato la candidatura o che un datore di lavoro sia interessato.","Una revisione di 138 esperimenti ha trovato benefici medi dall'aumento del monitoraggio dei progressi. Non ha validato queste annotazioni né una scadenza ideale per rivederle. Decidi dai fatti: ripeti un passo fattibile, modifica un problema, chiedi un parere o lascia un obiettivo inadatto. Se non hai provato, riconosci quel vuoto e realizza la prima parte utile."],practice:["Fai il primo piccolo tentativo o stabilisci esattamente quando lo farai.","Scegli una data ragionevole per rivedere il risultato e chiediti: «Cosa ho provato? Cosa ho imparato?»","Scegli ciò che è più adatto: continuare, ridurre, chiedere aiuto o cambiare obiettivo."],reflection:"In quale giorno rivedrai il piano e quali informazioni guarderai?",question:"Se il risultato desiderato non arriva, quale revisione è più utile?",options:["I miei pensieri non erano abbastanza forti.","Guardo azioni tentate e condizioni, poi scelgo il prossimo passo.","Mantengo la stessa aspettativa senza guardare la realtà."],correct:1,feedback:"Confrontare piano e realtà dà nuove informazioni. Nessun corso garantisce un risultato; puoi valutare insieme ciò che hai fatto e le condizioni esterne.",takeaway:"Lascia che le annotazioni cambino il prossimo passo. Impegno, preparazione e risultati esterni raccontano cose diverse.",sources:["M03","M01"],deeper:[{heading:"Monitorare aiuta a decidere",paragraphs:["La revisione del 2016 di Harkin e colleghi comprendeva 138 esperimenti con assegnazione casuale e 19.951 partecipanti complessivi. L'analisi sul raggiungimento degli obiettivi usava 18.398 persone e trovava d = 0,40, intervallo di confidenza al 95% da 0,32 a 0,48. Una correzione di sensibilità per studi piccoli dava una stima inferiore. Interventi, obiettivi e metodi di annotazione differivano. La revisione non ha sperimentato il resoconto ODA né la scheda del giorno dopo. [M03]","Tra gli studi, annotare o condividere pubblicamente i progressi era associato a effetti maggiori. Questi confronti tra studi con caratteristiche diverse non dimostrano che serva esporsi pubblicamente o che un formato dell’app causi benefici. Tieni privati i dettagli personali se è adatto alla tua situazione. Confronta ciò che chiedeva il piano con l'azione che hai riferito. Se manca un'annotazione, l'esito resta sconosciuto. Preparazione completata, richiesta senza risposta e tentativo interrotto devono conservare ciascuno il proprio nome. Così puoi valutare la prossima decisione senza dover raccontare una storia positiva."]},{heading:"Scegli il prossimo passo senza riscrivere questa settimana",paragraphs:["Un breve diario personale può suggerire un andamento, ma non dimostra perché si sia verificato un risultato esterno. Candidature, ordini e risposte altrui possono dipendere da qualità, tempi, risorse o condizioni che il diario non misura. La ricerca sul monitoraggio sostiene l'uso delle informazioni; non stabilisce un numero universale di tentativi prima di cambiare obiettivo. [M03] La revisione deve mantenere visibile questa incertezza.","Scegli una prossima occasione fattibile e quando rivederla nella settimana in arrivo. Mantieni il minimo utile e ciò che ha favorito l'accesso al compito; cambia la parte messa in discussione dalle annotazioni. Se non hai annotato tentativi, riferisci fatti conosciuti o considera il prossimo piccolo gesto il primo esperimento. Non inventare impegno passato. Gli studi sui piani mostrano benefici medi variabili, non risultati garantiti. [M01] Fermarti, chiedere un parere, trovare aiuto pratico o cambiare direzione possono essere decisioni consapevoli della revisione. Conserva le annotazioni precedenti, così resta visibile il motivo della scelta."]}],example:{title:"Daniele sceglie il passo della prossima settimana",text:"Daniele rilegge tre modifiche datate e un'occasione mancata al computer. Il curriculum è più chiaro, ma non ha inviato candidature. Sceglie un'offerta adatta, controlla i requisiti e venerdì invia la versione preparata. Annota l'invio e decide di rivederlo la settimana prossima. Non ha ancora ricevuto risposta."}},...n.map(r)]},p=Object.freeze(Object.defineProperty({__proto__:null,COURSE:u,MANIFEST_LESSONS_V2:a,SOURCES:c},Symbol.toStringTag,{value:"Module"}));export{p as m};
